escenas.Mundo:
// Mundo compartido: «El bebé que cayó dos veces sobre el mismo hombre» (Detroit, 1937 y 1938).
// Maqueta de un edificio de cuatro pisos de los años treinta, con su acera y un callejón a la derecha.
// Qué se ve al EMPEZAR cada paso:
// 0: noche cálida. La ventana del 4.º piso está abierta y el bebé amarillo asomado; Figlock (naranja) mira hacia arriba y la escoba está apoyada en la pared.
// 1-2: Figlock con la escoba en la mano, bajo el foco cálido; el bebé sigue en la ventana.
// 3: Figlock en el suelo con el bebé en brazos y la escoba tirada, bajo el foco cálido.
// 4: acera vacía, ventana cerrada, luz fría y el calendario (1938) flotando frente al edificio.
// 5: Figlock en el callejón con la escoba, bajo una luz fría; la ventana está cerrada.
// 6: la ventana abierta con el niño amarillo asomado y Figlock abajo; la luz sigue fría.
// 7: el niño en el aire y el foco cálido sobre Figlock, que mira hacia arriba.
// 8: Figlock y el niño sentados en el callejón, con un halo cálido.
// 9: el recorte de la revista Time flota frente al callejón, que queda en penumbra.
// 10: la pila de copias del recorte en primer plano, con un solo foco; el callejón está oscuro.
import React from 'react';
import {Pieza, Cartel, ConoDeLuz, Linea, flotar} from '../lib3d';
import type {Paleta, V3} from '../lib3d';
import {Persona2D, Sombra} from '../lib25d';

export const PARTES = ['ventana', 'bebe', 'figlock', 'escoba', 'foco', 'calendario', 'revista', 'copias'] as const;

export type ParteProps = {paleta: Paleta; resaltado?: boolean; frame?: number};
export type MundoProps = {paso: number; frame: number; fps: number; paleta: Paleta; ocultar?: string[]; resaltar?: string[]};

// ---------- Medidas de la maqueta ----------
const S = 0.08; // altura de la acera (encima de la base de la maqueta)
const PISO = 0.42;
export const VENTANA: V3 = [0.12, S + PISO * 3 + 0.24, 0.2];
export const POS_FIGLOCK: V3 = [0.22, S, 0.44];
export const POS_FIGLOCK_1938: V3 = [0.3, S, 0.36];
export const POS_CALENDARIO: V3 = [-0.18, 1.05, 0.72];
export const POS_REVISTA: V3 = [0.38, 1.05, 0.72];
export const POS_COPIAS: V3 = [0.22, S, 0.66];

const NARANJA = '#E2672A';
const AMARILLO = '#F4CB4A';
const LADRILLO = '#5E3B33';
const LADRILLO_OSC = '#45302B';
const PIEDRA = '#B9A88E';
const VIDRIO = '#20232E';
const PAPEL = '#D9C48E';
const TINTA_PAPEL = '#3A3226';

// ---------- Estado por paso ----------
export type EstadoFiglock = 'mira' | 'parado' | 'suelo' | 'sentado' | 'ninguno';
export type EstadoBebe = 'ventana' | 'aire' | 'brazos' | 'sentado' | 'ninguno';
export type EstadoEscoba = 'mano' | 'pared' | 'tirada' | 'ninguno';

export const aperturaVentana = (paso: number) => (paso <= 3 || (paso >= 6 && paso <= 9) ? 1 : 0);
export const anioCalendario = (paso: number) => (paso >= 4 ? 1938 : 1937);
export const posFiglock = (paso: number): V3 => (paso >= 4 ? POS_FIGLOCK_1938 : POS_FIGLOCK);
export const estadoFiglock = (paso: number): EstadoFiglock =>
  paso === 0 || paso === 7 ? 'mira' : paso <= 2 || paso === 5 || paso === 6 ? 'parado' : paso === 3 ? 'suelo' : paso === 8 || paso === 9 ? 'sentado' : 'ninguno';
export const estadoBebe = (paso: number): EstadoBebe =>
  paso <= 2 || paso === 6 ? 'ventana' : paso === 3 ? 'brazos' : paso === 7 ? 'aire' : paso === 8 || paso === 9 ? 'sentado' : 'ninguno';
export const estadoEscoba = (paso: number): EstadoEscoba =>
  paso === 0 ? 'pared' : paso <= 2 || (paso >= 5 && paso <= 7) ? 'mano' : paso === 3 || paso === 8 ? 'tirada' : 'ninguno';
/** 0 = noche cálida, 0.5 = luz fría, 1 = penumbra (solo el foco). */
export const penumbra = (paso: number) => (paso >= 9 ? 1 : paso >= 4 && paso <= 6 ? 0.5 : 0);
export const focoDe = (paso: number, paleta: Paleta): {color: string; fuerza: number; pos: V3; radio: number} => {
  if (paso >= 4 && paso <= 6) return {color: paleta.acentos[3], fuerza: 0.55, pos: POS_FIGLOCK_1938, radio: 0.42};
  if (paso === 9) return {color: paleta.acentos[2], fuerza: 1, pos: [POS_REVISTA[0], S, POS_REVISTA[2]], radio: 0.55};
  if (paso >= 10) return {color: paleta.acentos[2], fuerza: 1, pos: POS_COPIAS, radio: 0.45};
  return {color: paleta.acentos[2], fuerza: paso === 8 ? 1.15 : 1, pos: posFiglock(paso), radio: 0.38};
};

// ---------- Partes ----------

/** Ventana del cuarto piso: dos hojas que se abren hacia fuera; dentro, una lámpara encendida. */
export const Ventana: React.FC<ParteProps & {abierta?: number}> = ({paleta, resaltado, abierta = 1}) => {
  const marco = resaltado ? paleta.acentos[2] : '#3D4A44';
  const a = Math.max(0, Math.min(1, abierta));
  const hoja = (lado: 1 | -1) => (
    <group position={[-0.1 * lado, 0, 0.03]} rotation={[0, -lado * a * 1.75, 0]}>
      <Pieza forma="caja" medidas={[0.1, 0.26, 0.015]} color={marco} posicion={[0.05 * lado, 0, 0]} />
      <Pieza forma="caja" medidas={[0.07, 0.2, 0.017]} color={VIDRIO} posicion={[0.05 * lado, 0, 0]} contorno={false} />
    </group>
  );
  return (
    <group position={VENTANA}>
      <Pieza forma="caja" medidas={[0.2, 0.26, 0.02]} color={a > 0 ? '#5A3E22' : VIDRIO} brillo={a > 0 ? '#B07A2A' : undefined} posicion={[0, 0, 0.005]} />
      <Pieza forma="caja" medidas={[0.28, 0.04, 0.05]} color={resaltado ? paleta.acentos[2] : PIEDRA} posicion={[0, 0.15, 0.02]} />
      <Pieza forma="caja" medidas={[0.28, 0.035, 0.07]} color={resaltado ? paleta.acentos[2] : PIEDRA} posicion={[0, -0.14, 0.035]} />
      {hoja(1)}
      {hoja(-1)}
    </group>
  );
};

/** El bebé (1937) o el niño David Thomas (1938): figurita amarilla envuelta en su manta. */
export const Bebe: React.FC<ParteProps & {donde?: EstadoBebe; fps?: number}> = ({paleta, resaltado, frame = 0, donde = 'ventana', fps = 30}) => {
  if (donde === 'ninguno') return null;
  const color = resaltado ? paleta.acentos[2] : AMARILLO;
  const pos: V3 =
    donde === 'ventana'
      ? [VENTANA[0], VENTANA[1] - 0.14, VENTANA[2] + 0.025]
      : donde === 'aire'
        ? [VENTANA[0] + 0.05, 0.95 + flotar(frame, 0.01, 50), 0.34]
        : donde === 'brazos'
          ? [POS_FIGLOCK[0] - 0.22, S + 0.05, POS_FIGLOCK[2] + 0.03]
          : [POS_FIGLOCK_1938[0] + 0.14, S, POS_FIGLOCK_1938[2] + 0.05];
  return (
    <group position={pos} rotation={[0, 0, donde === 'aire' ? 0.5 : 0]}>
      <Persona2D pose={donde === 'aire' ? 'sorprendida' : 'parado'} color={color} alto={0.14} posicion={[0, 0, 0]} frame={frame} fps={fps} />
      {donde === 'sentado' ? <Sombra posicion={[0, 0.002, 0]} radio={0.08} /> : null}
    </group>
  );
};

/** Joseph Figlock, barrendero: figura naranja sin rostro. */
export const Figlock: React.FC<ParteProps & {estado?: EstadoFiglock; posicion?: V3; fps?: number}> = ({
  paleta,
  resaltado,
  frame = 0,
  estado = 'parado',
  posicion = POS_FIGLOCK,
  fps = 30,
}) => {
  if (estado === 'ninguno') return null;
  const color = resaltado ? paleta.acentos[2] : NARANJA;
  const pose = estado === 'mira' ? 'sorprendida' : 'parado';
  const giro = estado === 'suelo' ? Math.PI / 2 : estado === 'sentado' ? 0.12 : 0;
  const escala: V3 = estado === 'sentado' ? [1, 0.68, 1] : [1, 1, 1];
  const alza = estado === 'suelo' ? 0.045 : 0;
  return (
    <group position={posicion}>
      <Sombra posicion={[estado === 'suelo' ? -0.2 : 0, 0.002, 0]} radio={estado === 'suelo' ? 0.26 : 0.16} />
      <group position={[0, alza, 0]} rotation={[0, 0, giro]} scale={escala}>
        <Persona2D pose={pose} color={color} alto={0.42} posicion={[0, 0, 0]} espejo={estado === 'parado'} frame={frame} fps={fps} />
      </group>
    </group>
  );
};

/** Escoba de barrendero: palo de madera, cabeza y cerdas de paja. */
export const Escoba: React.FC<ParteProps & {estado?: EstadoEscoba; posicion?: V3}> = ({paleta, resaltado, estado = 'mano', posicion = POS_FIGLOCK}) => {
  if (estado === 'ninguno') return null;
  const palo = resaltado ? paleta.acentos[2] : '#8A5A34';
  const donde: V3 =
    estado === 'mano' ? [posicion[0] + 0.12, S, posicion[2] + 0.04] : estado === 'pared' ? [0.37, S, 0.08] : [0.55, S + 0.02, 0.62];
  const rot: V3 = estado === 'mano' ? [0, 0, 0.28] : estado === 'pared' ? [0, 0, 0.22] : [0, 0.45, Math.PI / 2];
  return (
    <group position={donde} rotation={rot}>
      <Pieza forma="caja" medidas={[0.14, 0.04, 0.035]} color={resaltado ? paleta.acentos[2] : '#C9A35A'} posicion={[0, 0.02, 0]} />
      <Pieza forma="caja" medidas={[0.13, 0.03, 0.045]} color="#4A3326" posicion={[0, 0.055, 0]} />
      <Pieza forma="cilindro" medidas={[0.008, 0.009, 0.4]} color={palo} posicion={[0, 0.27, 0]} />
      {estado !== 'mano' ? <Sombra posicion={[0, -0.01, 0]} radio={0.1} /> : null}
    </group>
  );
};

/** Calendario de pared gigante que flota frente al edificio. */
export const Calendario: React.FC<ParteProps & {anio?: number}> = ({paleta, resaltado, frame = 0, anio = 1938}) => (
  <group position={[POS_CALENDARIO[0], POS_CALENDARIO[1] + flotar(frame, 0.015, 90), POS_CALENDARIO[2]]} rotation={[0, 0.12, 0]}>
    <Pieza forma="caja" medidas={[0.5, 0.62, 0.03]} color="#3B2A22" />
    <Pieza forma="caja" medidas={[0.44, 0.5, 0.012]} color={resaltado ? paleta.acentos[2] : '#EDE6D6'} posicion={[0, -0.03, 0.02]} />
    <Pieza forma="caja" medidas={[0.5, 0.07, 0.045]} color={paleta.acentos[0]} posicion={[0, 0.28, 0.01]} />
    {[-0.13, 0.13].map((x) => (
      <Pieza key={x} forma="toro" medidas={[0.025, 0.006]} color="#9A9DA6" posicion={[x, 0.32, 0.03]} metal={0.6} />
    ))}
    {[-0.16, -0.21].map((y) => (
      <Pieza key={y} forma="caja" medidas={[0.34, 0.012, 0.004]} color="#8C8F99" posicion={[0, y, 0.028]} contorno={false} />
    ))}
    <Cartel texto={String(anio)} posicion={[0, 0.02, 0.04]} alto={0.17} fondo="transparent" colorTexto="#1B1B1F" />
  </group>
);

const LineasDeTexto: React.FC<{x: number; y0: number; n: number; ancho: number; paso?: number}> = ({x, y0, n, ancho, paso = 0.065}) => (
  <>
    {Array.from({length: n}, (_, i) => (
      <Pieza key={i} forma="caja" medidas={[ancho * (i % 4 === 3 ? 0.7 : 1), 0.018, 0.003]} color={TINTA_PAPEL} posicion={[x, y0 - i * paso, 0.008]} contorno={false} />
    ))}
  </>
);

/** Recorte amarillento de la revista Time (octubre de 1938): encabezado ilegible, foto y columnas. */
export const Revista: React.FC<ParteProps> = ({paleta, resaltado, frame = 0}) => (
  <group position={[POS_REVISTA[0], POS_REVISTA[1] + flotar(frame, 0.012, 100), POS_REVISTA[2]]} rotation={[0, -0.12, 0.05]}>
    <Pieza forma="caja" medidas={[0.85, 1.1, 0.012]} color={resaltado ? paleta.acentos[2] : PAPEL} />
    <Pieza forma="caja" medidas={[0.68, 0.09, 0.004]} color={TINTA_PAPEL} posicion={[0, 0.44, 0.008]} contorno={false} />
    <Pieza forma="caja" medidas={[0.5, 0.03, 0.004]} color={TINTA_PAPEL} posicion={[0, 0.355, 0.008]} contorno={false} />
    <Pieza forma="caja" medidas={[0.32, 0.32, 0.006]} color="#8C8F99" posicion={[-0.19, 0.12, 0.008]} />
    <LineasDeTexto x={0.2} y0={0.26} n={6} ancho={0.32} />
    <LineasDeTexto x={0} y0={-0.1} n={4} ancho={0.7} />
    <Cartel texto="TIME · OCT. 1938" posicion={[0, -0.43, 0.02]} alto={0.08} fondo="#2A241C" colorTexto={PAPEL} />
  </group>
);

/** Pila de copias idénticas del recorte (la historia repetida sin otras fuentes). */
export const Copias: React.FC<ParteProps & {cantidad?: number}> = ({paleta, resaltado, cantidad = 10}) => (
  <group position={POS_COPIAS}>
    <Sombra posicion={[0, 0.002, 0]} radio={0.45} />
    {Array.from({length: cantidad}, (_, i) => (
      <Pieza
        key={i}
        forma="caja"
        medidas={[0.5, 0.012, 0.62]}
        color={resaltado ? paleta.acentos[2] : i % 2 ? '#CDB77E' : PAPEL}
        posicion={[Math.sin(i * 1.3) * 0.03, 0.006 + i * 0.013, Math.cos(i * 1.7) * 0.02]}
        rotacion={[0, Math.sin(i * 2.3) * 0.25, 0]}
      />
    ))}
    <group position={[0, 0.012 + cantidad * 0.013, 0]} rotation={[-Math.PI / 2, 0, Math.sin((cantidad - 1) * 2.3) * 0.25]}>
      <Pieza forma="caja" medidas={[0.38, 0.05, 0.004]} color={TINTA_PAPEL} posicion={[0, 0.22, 0]} contorno={false} />
      <Pieza forma="caja" medidas={[0.16, 0.16, 0.004]} color="#8C8F99" posicion={[-0.1, 0.06, 0]} contorno={false} />
      <Pieza forma="caja" medidas={[0.16, 0.02, 0.004]} color={TINTA_PAPEL} posicion={[0.12, 0.08, 0]} contorno={false} />
    </group>
    {[-1, 1].map((l) => (
      <Pieza key={l} forma="caja" medidas={[0.4, 0.52, 0.008]} color="#CDB77E" posicion={[0.2 * l, 0.26, -0.3]} rotacion={[-0.22, 0.3 * l, 0.06 * l]} />
    ))}
  </group>
);

/** Foco de teatro: cono de luz visible, mancha en el suelo y algo de luz real. */
export const Foco: React.FC<ParteProps & {color?: string; fuerza?: number; posicion?: V3; radio?: number}> = ({
  paleta,
  resaltado,
  color,
  fuerza = 1,
  posicion = POS_FIGLOCK,
  radio = 0.38,
}) => {
  const c = resaltado ? paleta.acentos[2] : color ?? paleta.acentos[2];
  if (fuerza <= 0.001) return null;
  return (
    <group>
      <ConoDeLuz posicion={[posicion[0], S, posicion[2]]} altura={1.95} radio={radio} color={c} opacidad={0.09 * fuerza} />
      <mesh position={[posicion[0], S + 0.004, posicion[2]]} rotation={[-Math.PI / 2, 0, 0]}>
        <circleGeometry args={[radio * 0.95, 40]} />
        <meshBasicMaterial color={c} transparent opacity={0.22 * fuerza} depthWrite={false} toneMapped={false} />
      </mesh>
      <pointLight color={c} intensity={2.4 * fuerza} distance={2.6} decay={2} position={[posicion[0], 0.95, posicion[2] + 0.3]} />
    </group>
  );
};

// ---------- Escenario (no se anima por partes) ----------

const Edificio: React.FC<{paleta: Paleta; pen: number}> = ({paleta, pen}) => {
  const luzVentana = pen > 0.7 ? '#33250F' : pen > 0 ? '#5E4219' : '#9C6E24';
  const columnas = [-0.72, -0.32, 0.12];
  const ventanas: React.ReactNode[] = [];
  for (let i = 1; i <= 3; i++) {
    columnas.forEach((x, c) => {
      if (i === 3 && c === 2) return; // la ventana protagonista es una parte aparte
      const y = S + PISO * i + 0.24;
      const encendida = (i + c) % 2 === 0;
      ventanas.push(
        <group key={`${i}-${c}`} position={[x, y, 0.2]}>
          <Pieza forma="caja" medidas={[0.2, 0.26, 0.02]} color={encendida ? '#4A3620' : VIDRIO} brillo={encendida ? luzVentana : undefined} posicion={[0, 0, 0.005]} />
          <Pieza forma="caja" medidas={[0.26, 0.03, 0.05]} color={PIEDRA} posicion={[0, -0.145, 0.02]} />
        </group>,
      );
    });
  }
  return (
    <group>
      {/* base de la maqueta, acera, bordillo y callejón */}
      <Sombra posicion={[0, 0, 0]} radio={1.35} />
      <Pieza forma="caja" medidas={[2.35, 0.06, 1.75]} color="#2A211D" posicion={[0, 0.03, -0.05]} />
      <Pieza forma="caja" medidas={[2.25, 0.022, 0.56]} color="#55575E" posicion={[0, 0.071, 0.5]} />
      <Pieza forma="caja" medidas={[2.25, 0.03, 0.04]} color="#6E7078" posicion={[0, 0.075, 0.79]} />
      <Pieza forma="caja" medidas={[0.62, 0.02, 0.72]} color="#33343B" posicion={[0.66, 0.07, -0.15]} />
      {/* cuerpo del edificio, bandas de cada piso y cornisa */}
      <Pieza forma="caja" medidas={[1.27, PISO * 4, 0.7]} color={LADRILLO} posicion={[-0.315, S + PISO * 2, -0.15]} />
      {[1, 2, 3].map((i) => (
        <Pieza key={i} forma="caja" medidas={[1.3, 0.03, 0.73]} color={PIEDRA} posicion={[-0.315, S + PISO * i, -0.15]} />
      ))}
      <Pieza forma="caja" medidas={[1.35, 0.08, 0.78]} color={PIEDRA} posicion={[-0.315, S + PISO * 4 + 0.04, -0.15]} />
      <Pieza forma="caja" medidas={[0.12, 0.16, 0.12]} color={LADRILLO_OSC} posicion={[-0.7, S + PISO * 4 + 0.16, -0.32]} />
      <Pieza forma="cilindro" medidas={[0.1, 0.1, 0.16]} color="#5B4A3C" posicion={[-0.1, S + PISO * 4 + 0.16, -0.3]} />
      <Pieza forma="cono" medidas={[0.11, 0.07]} color="#4A3B30" posicion={[-0.1, S + PISO * 4 + 0.28, -0.3]} />
      {ventanas}
      {/* planta baja: puerta, escalón, escaparates con toldo y letrero */}
      <Pieza forma="caja" medidas={[0.22, 0.32, 0.02]} color="#3B2A22" posicion={[-0.32, S + 0.16, 0.205]} />
      <Pieza forma="caja" medidas={[0.32, 0.04, 0.12]} color={PIEDRA} posicion={[-0.32, S + 0.02, 0.26]} />
      {[-0.72, 0.12].map((x) => (
        <group key={x}>
          <Pieza forma="caja" medidas={[0.3, 0.22, 0.02]} color="#4A3620" brillo={luzVentana} posicion={[x, S + 0.16, 0.205]} />
          <Pieza forma="caja" medidas={[0.36, 0.03, 0.14]} color="#2F4F5A" posicion={[x, S + 0.33, 0.26]} rotacion={[0.3, 0, 0]} />
        </group>
      ))}
      <Cartel texto="DETROIT" posicion={[-0.32, S + 0.37, 0.23]} alto={0.06} fondo={paleta.acentos[4]} colorTexto={paleta.acentos[2]} />
      {/* escalera de incendios en el lado del callejón */}
      {[1, 2, 3].map((i) => (
        <Pieza key={i} forma="caja" medidas={[0.07, 0.012, 0.36]} color="#2B2D33" posicion={[0.36, S + PISO * i + 0.01, -0.15]} />
      ))}
      <Linea desde={[0.39, S + PISO, -0.3]} hasta={[0.39, S + PISO * 3 + 0.12, -0.3]} grosor={0.006} color="#2B2D33" />
      <Linea desde={[0.39, S + PISO, 0.02]} hasta={[0.39, S + PISO * 3 + 0.12, 0.02]} grosor={0.006} color="#2B2D33" />
      {/* muro del edificio vecino que cierra el callejón */}
      <Pieza forma="caja" medidas={[0.14, 1.05, 0.75]} color={LADRILLO_OSC} posicion={[1.02, S + 0.525, -0.12]} />
      <Pieza forma="caja" medidas={[0.16, 0.03, 0.77]} color="#6B5A4A" posicion={[1.02, S + 1.06, -0.12]} />
      {/* cubos de basura y un cajón en el callejón */}
      {[[0.76, -0.3], [0.86, -0.1]].map(([x, z]) => (
        <group key={x} position={[x, S, z]}>
          <Sombra posicion={[0, 0.002, 0]} radio={0.1} />
          <Pieza forma="cilindro" medidas={[0.07, 0.062, 0.16]} color="#6E727C" posicion={[0, 0.08, 0]} metal={0.3} />
          <Pieza forma="cilindro" medidas={[0.078, 0.078, 0.015]} color="#8C8F99" posicion={[0, 0.165, 0]} metal={0.3} />
        </group>
      ))}
      <Pieza forma="caja" medidas={[0.16, 0.12, 0.14]} color="#7A5A3A" posicion={[0.62, S + 0.06, -0.38]} rotacion={[0, 0.3, 0]} />
      {/* farola de gas en la acera */}
      <group position={[-1.02, S, 0.62]}>
        <Sombra posicion={[0, 0.002, 0]} radio={0.12} />
        <Pieza forma="cilindro" medidas={[0.04, 0.05, 0.05]} color="#24262C" posicion={[0, 0.025, 0]} />
        <Pieza forma="cilindro" medidas={[0.013, 0.018, 0.82]} color="#24262C" posicion={[0, 0.43, 0]} />
        <Pieza forma="caja" medidas={[0.08, 0.11, 0.08]} color="#E9C27A" brillo={pen > 0.7 ? '#4A3410' : '#C9892A'} posicion={[0, 0.9, 0]} />
        <Pieza forma="cono" medidas={[0.07, 0.06]} color="#24262C" posicion={[0, 0.985, 0]} />
        {pen < 0.9 ? <pointLight color="#F0B44C" intensity={0.9 * (1 - pen * 0.7)} distance={1.8} decay={2} position={[0, 0.9, 0.12]} /> : null}
      </group>
    </group>
  );
};

// ---------- Mundo completo ----------

export const Mundo: React.FC<MundoProps> = ({paso, frame, fps, paleta, ocultar = [], resaltar = []}) => {
  const ve = (n: string) => !ocultar.includes(n);
  const r = (n: string) => resaltar.includes(n);
  const pos = posFiglock(paso);
  const foco = focoDe(paso, paleta);
  return (
    <group>
      <Edificio paleta={paleta} pen={penumbra(paso)} />
      {ve('ventana') ? <Ventana paleta={paleta} resaltado={r('ventana')} abierta={aperturaVentana(paso)} frame={frame} /> : null}
      {ve('foco') ? <Foco paleta={paleta} resaltado={r('foco')} color={foco.color} fuerza={foco.fuerza} posicion={foco.pos} radio={foco.radio} /> : null}
      {ve('figlock') ? <Figlock paleta={paleta} resaltado={r('figlock')} estado={estadoFiglock(paso)} posicion={pos} frame={frame} fps={fps} /> : null}
      {ve('bebe') ? <Bebe paleta={paleta} resaltado={r('bebe')} donde={estadoBebe(paso)} frame={frame} fps={fps} /> : null}
      {ve('escoba') ? <Escoba paleta={paleta} resaltado={r('escoba')} estado={estadoEscoba(paso)} posicion={pos} /> : null}
      {ve('calendario') && paso === 4 ? <Calendario paleta={paleta} resaltado={r('calendario')} anio={anioCalendario(paso)} frame={frame} /> : null}
      {ve('revista') && paso === 9 ? <Revista paleta={paleta} resaltado={r('revista')} frame={frame} /> : null}
      {ve('copias') && paso >= 10 ? <Copias paleta={paleta} resaltado={r('copias')} /> : null}
    </group>
  );
};

escenas.Escena1:
// Escena 2 · «Abajo, un barrendero limpia un callejón. Se llama Joseph Figlock.»
// 3D: el edificio, la escoba que barre y una boca de incendios delante. 2D: Figlock, el polvo y el destello.
import React from 'react';
import {interpolate, Easing} from 'remotion';
import {EscenaProps, Pieza, Linea, Etiqueta, aparecer, momento} from '../lib3d';
import {Efecto, Sombra} from '../lib25d';
import {Mundo, Escoba, VENTANA, posFiglock} from './Mundo';

const PASO = 1;
const S = 0.08;

export const Escena1: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [rojo, gris, resalte, extra] = paleta.acentos;
  const fin = duracion ?? Math.round(4.66 * fps);

  // Momentos que marca la voz
  const tAbajo = momento(palabras, fps, 'abajo', 1);
  const tBarrendero = momento(palabras, fps, 'barrendero', Math.round(0.9 * fps));
  const tCallejon = momento(palabras, fps, 'callejón', Math.round(1.9 * fps));
  const tJoseph = momento(palabras, fps, 'joseph', Math.round(3.75 * fps));
  const tFiglock = momento(palabras, fps, 'figlock', Math.round(4.13 * fps));

  const pos = posFiglock(PASO);

  // 1) «Abajo»: una línea punteada baja desde la ventana hasta Figlock y luego se recoge.
  const baja = aparecer(frame, tAbajo, 16);
  const recoge = interpolate(frame, [tAbajo + 34, tAbajo + 46], [1, 0], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
  const trazo = baja * recoge;

  // 2) «barrendero»: la escoba barre de lado a lado y brilla un segundo y algo.
  const barre = interpolate(frame, [0, 5, fin - 18, fin - 6], [0, 1, 1, 0], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
  const vaiven = Math.sin(frame * 0.38) * barre;
  const escobaResaltada = frame >= tBarrendero && frame < tBarrendero + 38;
  const empuje = aparecer(frame, tBarrendero, 10); // al nombrar el oficio, barre con más ganas
  const dx = vaiven * (0.018 + 0.022 * empuje);
  const inclina = vaiven * (0.05 + 0.06 * empuje);

  // Polvo que levanta la escoba en cada pasada
  const pasada = Math.abs(Math.sin(frame * 0.38)) > 0.85 && barre > 0.5;

  // 3) «callejón»: etiqueta en el callejón, se va antes del nombre (máximo 2 textos).
  const eCallejon = aparecer(frame, tCallejon, 9) * (1 - aparecer(frame, tJoseph - 12, 8));

  // 4) «Joseph… Figlock»: su nombre aparece y la figura se resalta, luego vuelve a su naranja.
  const eNombre = aparecer(frame, tJoseph, 10);
  const figResaltado = frame >= tJoseph && frame < Math.min(tJoseph + 40, fin - 3);
  const destello = frame >= tFiglock && frame < tFiglock + 14;

  // Su sombra se alarga detrás de él (y se apaga al final para empalmar con el paso siguiente)
  const largo = interpolate(frame, [0, fin * 0.8], [0.18, 0.62], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
    easing: Easing.inOut(Easing.cubic),
  });
  const opSombra = 0.42 * interpolate(frame, [fin - 14, fin - 2], [1, 0], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});

  const resaltar = figResaltado ? ['figlock'] : [];

  return (
    <group>
      {/* Base: el mundo del paso 1 sin la escoba (la escoba la anima esta escena) */}
      <Mundo paso={PASO} frame={frame} fps={fps} paleta={paleta} ocultar={['escoba']} resaltar={resaltar} />

      {/* Sombra larga de Figlock, proyectada por el foco hacia el fondo y a la izquierda */}
      {opSombra > 0.01 ? (
        <group position={[pos[0], S + 0.006, pos[2]]} rotation={[0, 0.55, 0]}>
          <mesh position={[0, 0, -largo / 2]} rotation={[-Math.PI / 2, 0, 0]} scale={[0.09, largo / 2, 1]}>
            <circleGeometry args={[1, 32]} />
            <meshBasicMaterial color="#05060A" transparent opacity={opSombra} depthWrite={false} />
          </mesh>
        </group>
      ) : null}

      {/* La escoba barriendo (vuelve exactamente a su sitio al final) */}
      <group position={[dx, 0, 0]}>
        <group position={[pos[0] + 0.12, S + 0.3, pos[2] + 0.04]} rotation={[0, 0, inclina]}>
          <group position={[-(pos[0] + 0.12), -(S + 0.3), -(pos[2] + 0.04)]}>
            <Escoba paleta={paleta} estado="mano" posicion={pos} resaltado={escobaResaltada} />
          </group>
        </group>
      </group>

      {/* Montoncito de polvo y hojas que va barriendo (capa media) */}
      <group position={[pos[0] + 0.22, S, pos[2] + 0.08]}>
        <Pieza forma="media_esfera" medidas={[0.045]} color="#6B6256" escala={[1.4, 0.45, 1]} />
        <Pieza forma="caja" medidas={[0.035, 0.004, 0.02]} color={extra} posicion={[0.05, 0.004, 0.03]} rotacion={[0, 0.7, 0]} />
        <Pieza forma="caja" medidas={[0.03, 0.004, 0.018]} color="#8A6A3A" posicion={[-0.04, 0.004, 0.04]} rotacion={[0, -0.4, 0]} />
        <Pieza forma="caja" medidas={[0.028, 0.004, 0.016]} color={rojo} posicion={[0.07, 0.004, -0.02]} rotacion={[0, 1.2, 0]} />
      </group>
      {pasada ? (
        <Efecto tipo="vapor" posicion={[pos[0] + 0.16 + dx, S + 0.03, pos[2] + 0.1]} tam={0.14} color={gris} frame={frame} fps={fps} />
      ) : null}

      {/* Capa delantera: boca de incendios de época junto al bordillo */}
      <group position={[-0.62, S, 0.68]}>
        <Sombra posicion={[0, 0.002, 0]} radio={0.09} />
        <Pieza forma="cilindro" medidas={[0.045, 0.05, 0.02]} color="#3A2E2A" posicion={[0, 0.01, 0]} />
        <Pieza forma="cilindro" medidas={[0.035, 0.038, 0.14]} color={rojo} posicion={[0, 0.09, 0]} />
        <Pieza forma="media_esfera" medidas={[0.036]} color={rojo} posicion={[0, 0.16, 0]} />
        <Pieza forma="cilindro" medidas={[0.008, 0.012, 0.02]} color="#9A9DA6" posicion={[0, 0.2, 0]} metal={0.5} />
        {[-1, 1].map((l) => (
          <Pieza key={l} forma="cilindro" medidas={[0.014, 0.014, 0.03]} color="#9A9DA6" posicion={[0.045 * l, 0.11, 0]} rotacion={[0, 0, Math.PI / 2]} metal={0.5} />
        ))}
        <Pieza forma="cilindro" medidas={[0.018, 0.018, 0.025]} color="#9A9DA6" posicion={[0, 0.1, 0.045]} rotacion={[Math.PI / 2, 0, 0]} metal={0.5} />
      </group>

      {/* Capa delantera: hojas secas y un periódico doblado sobre la acera */}
      <group position={[0.62, S + 0.003, 0.7]} rotation={[0, -0.5, 0]}>
        <Pieza forma="caja" medidas={[0.16, 0.006, 0.11]} color="#CFC6B0" />
        <Pieza forma="caja" medidas={[0.12, 0.002, 0.012]} color="#4A4238" posicion={[0, 0.004, -0.03]} contorno={false} />
        <Pieza forma="caja" medidas={[0.1, 0.002, 0.008]} color="#4A4238" posicion={[0, 0.004, 0.0]} contorno={false} />
        <Pieza forma="caja" medidas={[0.1, 0.002, 0.008]} color="#4A4238" posicion={[0, 0.004, 0.025]} contorno={false} />
      </group>
      {[[-0.25, 0.72, 0.4], [-0.1, 0.66, 1.9], [0.45, 0.62, 2.6]].map(([x, z, r]) => (
        <Pieza key={x} forma="caja" medidas={[0.035, 0.004, 0.02]} color={extra} posicion={[x, S + 0.003, z]} rotacion={[0, r, 0]} />
      ))}

      {/* «Abajo»: trayectoria punteada de la ventana del bebé hasta el barrendero */}
      {trazo > 0.01 ? (
        <Linea
          desde={[VENTANA[0] + 0.03, VENTANA[1] - 0.2, VENTANA[2] + 0.12]}
          hasta={[pos[0], S + 0.5, pos[2]]}
          grosor={0.008}
          color={resalte}
          progreso={trazo}
          brillo
          discontinua
        />
      ) : null}

      {/* Rótulos, solo cuando la voz los nombra */}
      <Etiqueta texto="callejón" punto={[0.68, S + 0.01, -0.12]} desplazamiento={[0.2, 0.62, 0.3]} escala={eCallejon} />
      <Etiqueta texto="joseph figlock" punto={[pos[0] - 0.04, S + 0.36, pos[2]]} desplazamiento={[-0.62, 0.42, 0.12]} escala={eNombre} color={resalte} />

      {/* Destello justo en «Figlock» */}
      {destello ? <Efecto tipo="destello" posicion={[pos[0], S + 0.3, pos[2] + 0.08]} tam={0.35} color={resalte} frame={frame} fps={fps} /> : null}
    </group>
  );
};

escenas.Escena2:
// Escena 3 · «El bebé cae justo sobre él, y Figlock amortigua el golpe.»
// 3D: el edificio, la ventana y la escoba (Mundo). 2D: el bebé que cae, Figlock que lo recibe,
// las ondas del golpe y el destello. Termina igual que <Mundo paso={3} />.
import React from 'react';
import {interpolate, Easing} from 'remotion';
import {EscenaProps, Flecha, Linea, Brillo, aparecer, momento, mover} from '../lib3d';
import type {V3} from '../lib3d';
import {Persona2D, Efecto, Sombra} from '../lib25d';
import {Mundo, Figlock, Bebe, Escoba, VENTANA, POS_FIGLOCK} from './Mundo';

const PASO = 2;
const AMARILLO = '#F4CB4A';
const NARANJA = '#E2672A';
const S = 0.08;

const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
const lerpV = (a: V3, b: V3, t: number): V3 => [lerp(a[0], b[0], t), lerp(a[1], b[1], t), lerp(a[2], b[2], t)];
const clamp01 = (x: number) => Math.max(0, Math.min(1, x));

export const Escena2: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [rojo, , resalte] = paleta.acentos;
  const f = (s: number) => Math.round(s * fps);

  // Golpes sincronizados con la voz
  const tBebe = momento(palabras, fps, 'bebé', f(0.23));
  const tCae = momento(palabras, fps, 'cae', f(0.46));
  const tJusto = momento(palabras, fps, 'justo', f(0.71));
  const tEl = momento(palabras, fps, 'él', f(1.39)); // el bebé llega a los brazos
  const tFig = momento(palabras, fps, 'Figlock', f(1.86));
  const tAm = momento(palabras, fps, 'amortigua', f(2.26));
  const tGolpe = momento(palabras, fps, 'golpe', f(2.84));
  const tSuelo = Math.min(tAm + 11, duracion - 8); // Figlock toca el suelo

  // ---------- El bebé ----------
  const inicioBebe: V3 = [VENTANA[0], VENTANA[1] - 0.14, VENTANA[2] + 0.025];
  const enBrazos: V3 = [POS_FIGLOCK[0] - 0.03, S + 0.27, POS_FIGLOCK[2] + 0.05];
  const finBebe: V3 = [POS_FIGLOCK[0] - 0.22, S + 0.05, POS_FIGLOCK[2] + 0.03];
  const bebeResaltado = frame >= tBebe && frame < tBebe + f(1.2);
  // Antes de caer: se asoma y se tambalea (anticipación)
  const tambaleo = frame < tCae ? Math.sin(frame * 0.6) * 0.18 * aparecer(frame, tBebe, 6) : 0;
  const caida = clamp01((frame - tCae) / Math.max(1, tEl - tCae));
  const posCaida: V3 = [
    lerp(inicioBebe[0], enBrazos[0], caida),
    lerp(inicioBebe[1] + 0.04, enBrazos[1], caida * caida) + (caida < 0.25 ? Math.sin(caida * Math.PI * 4) * 0.04 : 0),
    lerp(inicioBebe[2], enBrazos[2], caida),
  ];
  const tumbo = interpolate(frame, [tAm, tSuelo], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
    easing: Easing.in(Easing.quad),
  });
  const mecer = frame >= tEl && frame < tAm ? Math.sin((frame - tEl) * 0.35) * 0.012 : 0;
  const posBebe: V3 = frame < tEl ? posCaida : lerpV([enBrazos[0], enBrazos[1] + mecer, enBrazos[2]], finBebe, tumbo);
  const giroBebe = frame < tCae ? tambaleo : frame < tEl ? (frame - tCae) * 0.22 : 0.5 * (1 - tumbo);

  // ---------- Figlock ----------
  const figResaltado = frame >= tFig && frame < tFig + f(1.2);
  const colorFig = figResaltado ? resalte : NARANJA;
  const brazosAbiertos = frame >= tJusto && frame < tAm;
  // aplastado al recibir al bebé y al tocar el suelo
  const aplasta = 1 - 0.14 * Math.exp(-Math.max(0, frame - tEl) / 4) * (frame >= tEl ? 1 : 0);
  const rebote = frame >= tSuelo ? Math.exp(-(frame - tSuelo) / 4) * Math.sin((frame - tSuelo) / 1.5) * 0.08 : 0;
  const giroFig = (Math.PI / 2) * tumbo - rebote;
  const enSuelo = frame >= tSuelo + 8;

  // ---------- Escoba que sale volando ----------
  const vuelo = interpolate(frame, [tEl, tEl + 16], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
    easing: Easing.out(Easing.quad),
  });
  const desdeEsc: V3 = [POS_FIGLOCK[0] + 0.12, S, POS_FIGLOCK[2] + 0.04];
  const hastaEsc: V3 = [0.55, S + 0.02, 0.62];
  const posEsc: V3 = [
    lerp(desdeEsc[0], hastaEsc[0], vuelo),
    lerp(desdeEsc[1], hastaEsc[1], vuelo) + Math.sin(vuelo * Math.PI) * 0.35,
    lerp(desdeEsc[2], hastaEsc[2], vuelo),
  ];
  const rotEsc: V3 = [0, 0.45 * vuelo, lerp(0.28, Math.PI / 2, vuelo) + Math.sin(vuelo * Math.PI) * 2.6];
  const escobaAterriza = vuelo >= 1;

  // ---------- Señales encima del mundo ----------
  const trayecto = aparecer(frame, tCae - 3, 9) * (1 - aparecer(frame, tEl + 6, 8));
  const flechaPeso = aparecer(frame, tAm - 3, 7) * (1 - aparecer(frame, tGolpe + 4, 6));
  const destello = interpolate(frame, [tGolpe - 2, tGolpe + 2, tGolpe + 10], [0, 1, 0], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
  const pulsoCaptura = interpolate(frame, [tEl, tEl + 2, tEl + 12], [0, 1, 0], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
  const ondas = frame >= tSuelo - 1 && frame < tSuelo + 26;
  const ondasCaptura = frame >= tEl && frame < tEl + 18;
  const latido = mover(frame, [tAm, tAm + 6, tAm + 14], [1, 1.25, 1]);

  return (
    <group>
      <Mundo paso={PASO} frame={frame} fps={fps} paleta={paleta} ocultar={['bebe', 'figlock', 'escoba']} />

      {/* Trayectoria de la caída: de la ventana a los brazos */}
      {trayecto > 0.01 ? (
        <Linea desde={[inicioBebe[0], inicioBebe[1] - 0.02, inicioBebe[2] + 0.05]} hasta={[enBrazos[0], enBrazos[1] + 0.1, enBrazos[2]]}
          grosor={0.008} color={resalte} discontinua progreso={trayecto} brillo />
      ) : null}

      {/* Figlock: de pie con la escoba, abre los brazos, recibe y cae amortiguando */}
      {enSuelo ? (
        <Figlock paleta={paleta} estado="suelo" posicion={POS_FIGLOCK} resaltado={figResaltado} frame={frame} fps={fps} />
      ) : (
        <group position={POS_FIGLOCK}>
          <Sombra posicion={[-0.2 * tumbo, 0.002, 0]} radio={lerp(0.16, 0.26, tumbo)} />
          <group position={[0, 0.045 * tumbo, 0]} rotation={[0, 0, giroFig]} scale={[1 + (1 - aplasta) * 0.6, aplasta, 1]}>
            <Persona2D pose={brazosAbiertos ? 'sorprendida' : 'parado'} color={colorFig} alto={0.42} posicion={[0, 0, 0]}
              espejo={tumbo < 0.01} frame={frame} fps={fps} />
          </group>
        </group>
      )}

      {/* El bebé: se tambalea, cae girando y queda en brazos */}
      {frame >= tSuelo + 8 ? (
        <Bebe paleta={paleta} donde="brazos" frame={frame} fps={fps} resaltado={bebeResaltado} />
      ) : (
        <group position={posBebe} rotation={[0, 0, giroBebe]}>
          <Persona2D pose={frame >= tCae && frame < tEl ? 'sorprendida' : 'parado'} color={bebeResaltado ? resalte : AMARILLO}
            alto={0.14} posicion={[0, 0, 0]} frame={frame} fps={fps} />
        </group>
      )}

      {/* La escoba sale despedida hacia el callejón */}
      {escobaAterriza ? (
        <Escoba paleta={paleta} estado="tirada" posicion={POS_FIGLOCK} />
      ) : (
        <group position={posEsc} rotation={rotEsc}>
          <Escoba paleta={paleta} estado="mano" posicion={[-0.12, -S, -0.04]} />
        </group>
      )}

      {/* Captura: pequeño destello y ondas en los brazos */}
      {pulsoCaptura > 0.01 ? <Brillo posicion={[enBrazos[0], enBrazos[1] + 0.05, enBrazos[2] + 0.05]} color={resalte} radio={0.05 * pulsoCaptura} luz={1.5 * pulsoCaptura} /> : null}
      {ondasCaptura ? <Efecto tipo="ondas" posicion={[enBrazos[0], enBrazos[1] + 0.05, enBrazos[2] + 0.08]} tam={0.35} color={resalte} frame={frame - tEl} fps={fps} /> : null}

      {/* Amortigua: el peso del golpe baja sobre Figlock */}
      {flechaPeso > 0.01 ? (
        <group scale={[1, 1, 1]}>
          <Flecha desde={[POS_FIGLOCK[0] - 0.08, 1.05, POS_FIGLOCK[2] + 0.12]} hasta={[POS_FIGLOCK[0] - 0.08, 0.55, POS_FIGLOCK[2] + 0.12]}
            color={rojo} grosor={0.022 * latido} progreso={flechaPeso} />
        </group>
      ) : null}

      {/* Golpe contra la acera: ondas en el suelo y destello */}
      {ondas ? <Efecto tipo="ondas" posicion={[POS_FIGLOCK[0] - 0.18, S + 0.03, POS_FIGLOCK[2] + 0.08]} tam={0.5} color={resalte} frame={frame - tSuelo} fps={fps} /> : null}
      {frame >= tSuelo - 1 && frame < tSuelo + 20 ? (
        <Efecto tipo="chispa" posicion={[POS_FIGLOCK[0] - 0.2, S + 0.04, POS_FIGLOCK[2] + 0.1]} tam={0.3} color={paleta.acentos[1]} frame={frame - tSuelo} fps={fps} />
      ) : null}
      {destello > 0.01 ? (
        <>
          <Efecto tipo="destello" posicion={[POS_FIGLOCK[0] - 0.15, S + 0.12, POS_FIGLOCK[2] + 0.12]} tam={0.45 * destello} color={resalte} frame={frame - tGolpe} fps={fps} />
          <pointLight color={resalte} intensity={3 * destello} distance={2} decay={2} position={[POS_FIGLOCK[0], 0.5, POS_FIGLOCK[2] + 0.4]} />
        </>
      ) : null}
    </group>
  );
};

escenas.Escena0:
// Escena 1 (gancho): el bebé ya viene cayendo desde la ventana del cuarto piso sobre Figlock.
// Cae, lo atrapa, y en «dos veces» todo se rebobina hasta la ventana: el mundo queda como el paso 1.
import React from 'react';
import {EscenaProps, Pieza, Linea, Flecha, Etiqueta, Aro, aparecer, momento, mover} from '../lib3d';
import type {V3} from '../lib3d';
import {Persona2D, Sombra, Efecto} from '../lib25d';
import {Mundo, Figlock, Escoba, VENTANA, POS_FIGLOCK} from './Mundo';

const PASO = 0;
const S = 0.08;

export const Escena0: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [, gris, resalte, azul] = paleta.acentos;
  const tQue = momento(palabras, fps, 'probabilidad', 5);
  const tCaiga = momento(palabras, fps, 'caiga', 39);
  const tEncima = Math.max(tCaiga + 12, momento(palabras, fps, 'encima', 60));
  const tDos = momento(palabras, fps, 'Dos', 99);
  const tVeces = Math.max(tDos + 6, momento(palabras, fps, 'veces', 107));
  const tVuelve = Math.min(duracion - 6, tDos + 18); // el bebé ya está de vuelta en la ventana
  const tFin = duracion - 1;

  // ---- trayectoria del bebé ----
  const arriba: V3 = [VENTANA[0], VENTANA[1] - 0.14, VENTANA[2] + 0.025];
  const brazos: V3 = [POS_FIGLOCK[0] - 0.02, S + 0.44, POS_FIGLOCK[2] + 0.04];
  const caida = frame < tEncima ? 0.2 + 0.8 * Math.pow(Math.max(0, frame) / tEncima, 2) : 1;
  const rebob = frame < tDos ? 0 : Math.min(1, (frame - tDos) / (tVuelve - tDos));
  const rebobSuave = rebob * rebob * (3 - 2 * rebob);
  const p = frame < tDos ? caida : 1 - rebobSuave;

  // golpe al atrapar: Figlock se aplasta y recupera
  const fg = frame - tEncima;
  const aplasta = fg >= 0 && frame < tDos ? 1 - 0.22 * Math.exp(-fg / 5) * Math.abs(Math.cos(fg / 3)) : 1;
  const enBrazos = frame >= tEncima && frame < tDos;
  const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
  const bebeY = enBrazos ? S + 0.44 * aplasta + 0.02 * Math.abs(Math.sin(fg / 4)) * Math.exp(-fg / 12) : lerp(arriba[1], brazos[1], p);
  const bebePos: V3 = [lerp(arriba[0], brazos[0], p), bebeY, lerp(arriba[2], brazos[2], p)];
  const giroBebe = frame < tEncima ? 0.5 * Math.sin(frame * 0.35) : frame < tDos ? 0.15 * Math.exp(-fg / 10) : (1 - rebobSuave) * 3.5 * Math.sin(rebob * 9);
  const bebeResaltado = frame >= tCaiga && frame < tCaiga + 40;
  const bebeVisible = frame < tVuelve;

  // ---- Figlock: mira arriba y, al final, queda parado con la escoba ----
  const figlockParado = frame >= tVeces + 6;
  const figlockResaltado = frame >= tEncima && frame < tEncima + 36;
  const escobaListo = frame >= tFin - 2;
  const escobaPos: V3 = [
    mover(frame, [tVeces, tFin - 3], [0.25, POS_FIGLOCK[0]]),
    S,
    mover(frame, [tVeces, tFin - 3], [0.04, POS_FIGLOCK[2]]),
  ];

  // ---- golpes visuales ----
  const traza = aparecer(frame, 0, 9) * (frame < tDos ? 1 : 0);
  const flechaPeso = aparecer(frame, tCaiga, 10) * (frame < tEncima + 8 ? 1 : 0);
  const sombraBebe = frame < tEncima ? 0.06 + 0.26 * caida : 0;
  const destello = frame >= tEncima && frame < tEncima + 16;
  const etiqueta1 = aparecer(frame, tEncima + 2, 8) * (1 - aparecer(frame, tDos - 8, 8));
  const rebobTraza = frame >= tDos && frame < tVuelve + 4 ? 1 - rebobSuave * 0.0 : 0;
  const cierre = 1 - aparecer(frame, tFin - 7, 6);
  const aro1 = aparecer(frame, tDos, 8) * cierre;
  const aro2 = aparecer(frame, tVeces, 8) * cierre;
  const etiqueta2 = aparecer(frame, tVeces, 8) * cierre;
  const vibra = frame < tQue + 8 ? 0.015 * Math.sin(frame * 2.2) : 0;

  const ocultar = ['bebe', 'figlock', 'escoba'].filter((n) => !(n === 'bebe' && !bebeVisible));
  const resaltar = frame >= tDos && frame < tDos + 36 ? ['ventana'] : [];

  return (
    <group>
      <Mundo paso={PASO} frame={frame} fps={fps} paleta={paleta} ocultar={ocultar} resaltar={resaltar} />

      {/* Figlock con los brazos arriba (aplastado en el golpe) */}
      <group position={POS_FIGLOCK} scale={[1 + (1 - aplasta) * 0.5, aplasta, 1]}>
        <Figlock paleta={paleta} resaltado={figlockResaltado} estado={figlockParado ? 'parado' : 'mira'} posicion={[0, 0, 0]} frame={frame} fps={fps} />
      </group>

      {/* La escoba: de la pared a la mano */}
      {escobaListo ? (
        <Escoba paleta={paleta} estado="mano" posicion={POS_FIGLOCK} />
      ) : frame >= tVeces ? (
        <Escoba paleta={paleta} estado="mano" posicion={escobaPos} />
      ) : (
        <Escoba paleta={paleta} estado="pared" posicion={POS_FIGLOCK} />
      )}

      {/* El bebé cayendo (2D), con su sombra que crece sobre Figlock */}
      {bebeVisible ? (
        <group position={[bebePos[0] + vibra, bebePos[1], bebePos[2]]} rotation={[0, 0, giroBebe]}>
          <Persona2D pose={p > 0.02 && !enBrazos ? 'sorprendida' : 'parado'} color={bebeResaltado ? resalte : '#F4CB4A'} alto={0.14} posicion={[0, 0, 0]} frame={frame} fps={fps} />
        </group>
      ) : null}
      {sombraBebe > 0 ? <Sombra posicion={[POS_FIGLOCK[0], S + 0.003, POS_FIGLOCK[2] + 0.02]} radio={sombraBebe} /> : null}

      {/* trayectoria punteada ventana → brazos */}
      {traza > 0 ? <Linea desde={arriba} hasta={brazos} color={resalte} grosor={0.007} discontinua brillo progreso={traza} /> : null}
      {/* rebobinado: la línea se recorre hacia arriba */}
      {rebobTraza > 0 && frame < tVuelve ? (
        <Linea desde={brazos} hasta={arriba} color={azul} grosor={0.008} discontinua brillo progreso={rebobSuave} />
      ) : null}

      {/* rayas de velocidad sobre el bebé mientras cae */}
      {frame < tEncima && frame >= tCaiga - 20
        ? [-0.04, 0, 0.04].map((dx, i) => (
            <Linea key={dx} desde={[bebePos[0] + dx, bebePos[1] + 0.12 + i * 0.02, bebePos[2] - 0.01]} hasta={[bebePos[0] + dx, bebePos[1] + 0.26 + i * 0.04 + caida * 0.12, bebePos[2] - 0.01]} color="#F2EFE9" grosor={0.004} brillo />
          ))
        : null}

      {/* fuerza de la caída */}
      <Flecha desde={[-0.12, 1.25, 0.42]} hasta={[-0.12, 0.62, 0.42]} color={resalte} grosor={0.025} progreso={flechaPeso} />

      {/* impacto */}
      {destello ? <Efecto tipo="destello" posicion={[brazos[0], brazos[1] + 0.04, brazos[2] + 0.05]} tam={0.45} frame={frame - tEncima} fps={fps} /> : null}
      {destello ? <Efecto tipo="ondas" posicion={[POS_FIGLOCK[0], S + 0.01, POS_FIGLOCK[2] + 0.05]} tam={0.5} frame={frame - tEncima} fps={fps} /> : null}

      {/* el mismo punto de la acera, dos veces */}
      {aro1 > 0 ? <Aro posicion={[POS_FIGLOCK[0], S, POS_FIGLOCK[2]]} radio={0.2} color={resalte} progreso={aro1} /> : null}
      {aro2 > 0 ? <Aro posicion={[POS_FIGLOCK[0], S, POS_FIGLOCK[2]]} radio={0.28} color={azul} progreso={aro2} /> : null}

      {/* textos (nunca dos a la vez) */}
      <Etiqueta texto="un bebé encima" punto={[brazos[0] + 0.05, brazos[1] + 0.05, brazos[2]]} desplazamiento={[0.5, 0.35, 0.1]} escala={etiqueta1} />
      <Etiqueta texto="dos veces" punto={[POS_FIGLOCK[0] + 0.2, S + 0.02, POS_FIGLOCK[2]]} desplazamiento={[0.45, 0.5, 0.2]} escala={etiqueta2} color={resalte} />

      {/* primer plano: boca de incendios, periódico y cajón en la acera */}
      <group position={[-0.58, S, 0.7]}>
        <Sombra posicion={[0, 0.002, 0]} radio={0.1} />
        <Pieza forma="cilindro" medidas={[0.05, 0.06, 0.03]} color="#55585F" posicion={[0, 0.015, 0]} />
        <Pieza forma="cilindro" medidas={[0.038, 0.042, 0.16]} color={gris} posicion={[0, 0.11, 0]} metal={0.3} />
        <Pieza forma="media_esfera" medidas={[0.04]} color={gris} posicion={[0, 0.19, 0]} metal={0.3} />
        <Pieza forma="cilindro" medidas={[0.016, 0.016, 0.1]} color="#6E727C" posicion={[0, 0.13, 0]} rotacion={[0, 0, Math.PI / 2]} />
        <Pieza forma="cilindro" medidas={[0.01, 0.01, 0.02]} color="#6E727C" posicion={[0, 0.245, 0]} />
      </group>
      <Pieza forma="caja" medidas={[0.16, 0.006, 0.11]} color="#CFC6B0" posicion={[-0.28, S + 0.004, 0.66]} rotacion={[0, 0.5, 0]} />
      <Pieza forma="caja" medidas={[0.1, 0.007, 0.006]} color="#3A3226" posicion={[-0.28, S + 0.009, 0.66]} rotacion={[0, 0.5, 0]} contorno={false} />
      <group position={[0.84, S, 0.64]} rotation={[0, -0.4, 0]}>
        <Sombra posicion={[0, 0.002, 0]} radio={0.13} />
        <Pieza forma="caja" medidas={[0.18, 0.13, 0.15]} color="#7A5A3A" posicion={[0, 0.065, 0]} />
        <Pieza forma="caja" medidas={[0.19, 0.015, 0.16]} color="#5E4430" posicion={[0, 0.1, 0]} />
        <Pieza forma="caja" medidas={[0.19, 0.015, 0.16]} color="#5E4430" posicion={[0, 0.03, 0]} />
      </group>
    </group>
  );
};

escenas.Escena3:
// Escena 4 (paso 3): «Los dos sobreviven, aunque heridos. Pero lo más raro viene un año después.»
// Figlock se levanta con el bebé a salvo, recoge la escoba y se va al callejón; la luz se enfría,
// la ventana se cierra y el calendario aparece y pasa la hoja hasta el año siguiente.
import React from 'react';
import * as THREE from 'three';
import {interpolate, spring, Easing} from 'remotion';
import {EscenaProps, Etiqueta, Pieza, Cartel, aparecer, momento, rebote, flotar} from '../lib3d';
import type {V3} from '../lib3d';
import {Persona2D, Sombra} from '../lib25d';
import {Mundo, Ventana, Escoba, Foco, Calendario, POS_FIGLOCK, POS_FIGLOCK_1938, POS_CALENDARIO} from './Mundo';

const NARANJA = '#E2672A';
const AMARILLO = '#F4CB4A';
const S = 0.08;
const clamp = {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'} as const;

const mezclar = (a: string, b: string, t: number) => '#' + new THREE.Color(a).lerp(new THREE.Color(b), Math.max(0, Math.min(1, t))).getHexString();

export const Escena3: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const resalte = paleta.acentos[2];
  const frio = paleta.acentos[3];

  // Momentos de la voz
  const tDos = momento(palabras, fps, 'dos', 8);
  const tSobre = momento(palabras, fps, 'sobreviven', 13);
  const tHeridos = momento(palabras, fps, 'heridos', 44);
  const tPero = momento(palabras, fps, 'pero', 84);
  const tRaro = momento(palabras, fps, 'raro', 100);
  const tViene = momento(palabras, fps, 'viene', 107);
  const tAnio = momento(palabras, fps, 'año', 120);
  const tDespues = momento(palabras, fps, 'después', Math.min(127, duracion - 14));

  // Figlock se levanta (de tumbado a de pie) con un pequeño tambaleo al decir "heridos"
  const lev = Math.min(1, Math.max(0, spring({frame: frame - tSobre, fps, config: {damping: 12, stiffness: 110}})));
  const fh = frame - tHeridos;
  const tambaleo = fh > 0 ? 0.16 * Math.exp(-fh / 8) * Math.sin(fh / 2.2) : 0;
  const giro = (Math.PI / 2) * (1 - lev) + tambaleo;
  const alza = 0.045 * (1 - lev);

  // Camina: por la acera hasta la escoba y luego al fondo del callejón (≈0,75 m/s)
  const tCamina = tHeridos + 10;
  const tRecoge = tCamina + 14;
  const tCallejon = tRecoge + 32;
  const pX = interpolate(frame, [tCamina, tRecoge, tCallejon], [POS_FIGLOCK[0], 0.58, 0.66], clamp);
  const pZ = interpolate(frame, [tCamina, tRecoge, tCallejon], [POS_FIGLOCK[2], 0.5, -0.3], clamp);
  const camina = frame >= tCamina && frame < tCallejon;
  const figPos: V3 = [pX, S, pZ];
  const seVa = 1 - aparecer(frame, tCallejon, 12); // se pierde en la penumbra del callejón
  const resaltado = frame >= tDos && frame < tDos + 36;
  const colorFig = resaltado ? resalte : NARANJA;
  const colorBebe = resaltado ? resalte : AMARILLO;

  // Bebé: de los brazos en el suelo a la altura del pecho
  const bebeRel: V3 = [-0.22 + 0.29 * lev, 0.05 + 0.14 * lev, 0.03 + 0.01 * lev];
  const bote = camina ? Math.abs(Math.sin(frame / 3)) * 0.008 : 0;

  // Luz: cálida → fría, sigue a Figlock y luego se asienta en su lugar del paso siguiente
  const enfria = aparecer(frame, tPero, 16);
  const asienta = Easing.inOut(Easing.cubic)(aparecer(frame, tCallejon, 22));
  const focoPos: V3 = [
    pX + (POS_FIGLOCK_1938[0] - pX) * asienta,
    S,
    pZ + (POS_FIGLOCK_1938[2] - pZ) * asienta,
  ];
  const focoColor = mezclar(resalte, frio, enfria);
  const focoFuerza = 1 - 0.45 * aparecer(frame, tPero, 20);
  const focoRadio = 0.38 + 0.04 * enfria;

  // Ventana se cierra; calendario entra y pasa la hoja
  const ventana = 1 - aparecer(frame, tRaro, 12);
  const calEsc = frame >= tViene ? rebote(frame, fps, tViene) : 0;
  const hoja = Easing.inOut(Easing.cubic)(aparecer(frame, tAnio, 18));
  const flot = flotar(frame, 0.015, 90);

  const etiSobre = aparecer(frame, tSobre, 8) * (1 - aparecer(frame, tPero - 8, 8));
  const etiDespues = aparecer(frame, tDespues, 8);

  return (
    <group>
      <Mundo
        paso={frame >= tPero ? 4 : 3}
        frame={frame}
        fps={fps}
        paleta={paleta}
        ocultar={['figlock', 'bebe', 'escoba', 'foco', 'ventana', 'calendario']}
      />
      <Ventana paleta={paleta} abierta={ventana} />
      <Foco paleta={paleta} color={focoColor} fuerza={focoFuerza} posicion={focoPos} radio={focoRadio} />

      {/* Figlock y el bebé */}
      {seVa > 0.001 ? (
        <group position={figPos} scale={seVa}>
          <Sombra posicion={[-0.2 * (1 - lev), 0.002, 0]} radio={0.16 + 0.1 * (1 - lev)} />
          <group position={[0, alza, 0]} rotation={[0, 0, giro]}>
            <Persona2D pose={camina ? 'camina' : 'parado'} color={colorFig} alto={0.42} posicion={[0, 0, 0]} frame={frame} fps={fps} />
          </group>
          <group position={[bebeRel[0], bebeRel[1] + bote, bebeRel[2]]}>
            <Persona2D pose="parado" color={colorBebe} alto={0.14} posicion={[0, 0, 0]} frame={frame} fps={fps} />
          </group>
        </group>
      ) : null}

      {/* Escoba: tirada hasta que la recoge; luego va con él */}
      {frame < tRecoge ? (
        <Escoba paleta={paleta} estado="tirada" />
      ) : seVa > 0.001 ? (
        <group position={figPos} scale={seVa}>
          <group position={[-figPos[0], -figPos[1], -figPos[2]]}>
            <Escoba paleta={paleta} estado="mano" posicion={figPos} />
          </group>
        </group>
      ) : null}

      {/* Calendario con la hoja del año anterior que se levanta */}
      {calEsc > 0.001 ? (
        <group position={POS_CALENDARIO} scale={calEsc}>
          <group position={[-POS_CALENDARIO[0], -POS_CALENDARIO[1], -POS_CALENDARIO[2]]}>
            <Calendario paleta={paleta} anio={1938} frame={frame} />
            {hoja < 0.97 ? (
              <group position={[POS_CALENDARIO[0], POS_CALENDARIO[1] + flot, POS_CALENDARIO[2]]} rotation={[0, 0.12, 0]}>
                <group position={[0, 0.22, 0.05]} rotation={[-Math.PI * hoja, 0, 0]}>
                  <Pieza forma="caja" medidas={[0.44, 0.5, 0.008]} color="#EDE6D6" posicion={[0, -0.25, 0]} />
                  {[-0.16, -0.21].map((y) => (
                    <Pieza key={y} forma="caja" medidas={[0.34, 0.012, 0.004]} color="#8C8F99" posicion={[0, y - 0.22, 0.006]} contorno={false} />
                  ))}
                  <Cartel texto="1937" posicion={[0, -0.2, 0.008]} alto={0.17} fondo="transparent" colorTexto="#1B1B1F" rotacion={[0.0001, 0, 0]} />
                </group>
              </group>
            ) : null}
          </group>
        </group>
      ) : null}

      {/* Textos */}
      <Etiqueta texto="sobreviven" punto={[POS_FIGLOCK[0] - 0.05, S + 0.3, POS_FIGLOCK[2]]} desplazamiento={[-0.5, 0.42, 0.1]} escala={etiSobre} />
      <Etiqueta texto="un año después" punto={[POS_CALENDARIO[0] - 0.26, POS_CALENDARIO[1] + 0.12, POS_CALENDARIO[2]]} desplazamiento={[-0.2, 0.4, 0.05]} escala={etiDespues} />
    </group>
  );
}

escenas.Escena4:
// Escena 5 (PASO 4 → 5): «Mil novecientos treinta y ocho. Figlock vuelve a pasar junto al edificio.»
// 3D: la maqueta, el calendario que se despide y una boca de incendios delante. 2D: Figlock que camina.
import React from 'react';
import {EscenaProps, Pieza, Etiqueta, Linea, aparecer, momento, mover} from '../lib3d';
import {Persona2D, Sombra} from '../lib25d';
import {Mundo, Escoba, Calendario, POS_CALENDARIO, POS_FIGLOCK_1938, VENTANA} from './Mundo';

const PASO = 4;
const NARANJA = '#E2672A';
const S = 0.08;

export const Escena4: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const resalte = paleta.acentos[2];
  const gris = paleta.acentos[1];
  const fin = duracion - 1;

  const tMil = momento(palabras, fps, 'mil', 1);
  const tOcho = momento(palabras, fps, 'ocho', 38);
  const tFig = momento(palabras, fps, 'figlock', 72);
  const tVuelve = momento(palabras, fps, 'vuelve', 85);
  const tJunto = momento(palabras, fps, 'junto', 105);
  const tEdif = Math.min(momento(palabras, fps, 'edificio', 116), fin - 16);

  // --- Calendario: late en «mil», se resalta en «ocho» y se va hacia arriba en «vuelve» ---
  const fPulso = frame - tMil;
  const pulso = fPulso >= 0 ? 1 + 0.09 * Math.exp(-fPulso / 6) * Math.sin(fPulso / 2.2) : 1;
  const sale = aparecer(frame, tVuelve - 4, 16);
  const escCal = pulso * (1 - sale);
  const subeCal = sale * sale * 0.5;
  const calResaltado = frame >= tOcho && frame < tOcho + 40;
  const etiq = aparecer(frame, tOcho, 8) * (1 - aparecer(frame, tVuelve - 6, 8));

  // --- Figlock: entra por la izquierda caminando por la acera y se detiene bajo la luz fría ---
  const tEntra = tFig - 6;
  const tLlega = Math.min(tEntra + 46, fin - 18); // ~1,06 m en ~1,5 s (paso de caminar)
  const fx = mover(frame, [tEntra, tLlega], [-0.75, POS_FIGLOCK_1938[0]]);
  const fz = mover(frame, [tEntra, tLlega], [0.5, POS_FIGLOCK_1938[2]]);
  const caminando = frame >= tEntra && frame < tLlega;
  const llego = frame >= tLlega;
  const entra = aparecer(frame, tEntra, 6);
  const figResaltado = frame >= tFig && frame < tFig + 38;
  const colorFig = figResaltado ? resalte : NARANJA;

  // --- «edificio»: una línea punteada sube por la fachada hasta la ventana, que se resalta ---
  const subeLinea = aparecer(frame, tJunto, 14);
  const lineaVisible = frame >= tJunto && frame < fin - 3;
  const ventanaResaltada = frame >= tEdif - 2 && frame < Math.min(tEdif + 30, fin - 2);

  // Papel que el viento arrastra por la acera (capa delantera)
  const papelX = mover(frame, [0, fin], [-0.95, 0.15]);
  const papelY = S + 0.012 + Math.abs(Math.sin(frame / 7)) * 0.05;

  return (
    <group>
      <Mundo
        paso={PASO}
        frame={frame}
        fps={fps}
        paleta={paleta}
        ocultar={['figlock', 'escoba', 'calendario']}
        resaltar={ventanaResaltada ? ['ventana'] : []}
      />

      {/* Calendario 1938 (se despide de la escena) */}
      {escCal > 0.001 ? (
        <group position={[POS_CALENDARIO[0], POS_CALENDARIO[1] + subeCal, POS_CALENDARIO[2]]} scale={escCal}>
          <group position={[-POS_CALENDARIO[0], -POS_CALENDARIO[1], -POS_CALENDARIO[2]]}>
            <Calendario paleta={paleta} resaltado={calResaltado} anio={1938} frame={frame} />
          </group>
        </group>
      ) : null}
      <Etiqueta texto="1938" punto={[-0.43, 1.25, 0.74]} desplazamiento={[-0.32, 0.3, 0]} escala={etiq} color={resalte} />

      {/* Figlock caminando (2D) con su escoba (3D) */}
      {entra > 0 && !llego ? (
        <group position={[fx, S, fz]} scale={entra}>
          <Sombra posicion={[0, 0.002, 0]} radio={0.16} />
          <Persona2D pose={caminando ? 'camina' : 'parado'} color={colorFig} alto={0.42} posicion={[0, 0, 0]} frame={frame} fps={fps} />
        </group>
      ) : null}
      {llego ? (
        <group position={POS_FIGLOCK_1938}>
          <Sombra posicion={[0, 0.002, 0]} radio={0.16} />
          <Persona2D pose="parado" color={colorFig} alto={0.42} posicion={[0, 0, 0]} espejo frame={frame} fps={fps} />
        </group>
      ) : null}
      {entra > 0 ? (
        <group scale={1}>
          <Escoba paleta={paleta} estado="mano" posicion={[fx, S, fz]} resaltado={false} />
        </group>
      ) : null}

      {/* De la acera a la ventana: anticipa la subida de cámara */}
      {lineaVisible ? (
        <Linea
          desde={[POS_FIGLOCK_1938[0] - 0.04, 0.58, POS_FIGLOCK_1938[2] - 0.05]}
          hasta={[VENTANA[0] + 0.04, VENTANA[1] - 0.17, VENTANA[2] + 0.06]}
          grosor={0.007}
          color={resalte}
          progreso={subeLinea}
          discontinua
          brillo
        />
      ) : null}

      {/* Capa delantera: boca de incendios gris en el borde de la acera */}
      <group position={[-0.62, S, 0.7]}>
        <Sombra posicion={[0, 0.002, 0]} radio={0.08} />
        <Pieza forma="cilindro" medidas={[0.05, 0.055, 0.025]} color="#5E616B" posicion={[0, 0.012, 0]} />
        <Pieza forma="cilindro" medidas={[0.038, 0.042, 0.14]} color={gris} posicion={[0, 0.095, 0]} metal={0.3} />
        <Pieza forma="media_esfera" medidas={[0.04]} color={gris} posicion={[0, 0.165, 0]} metal={0.3} />
        <Pieza forma="cilindro" medidas={[0.008, 0.008, 0.02]} color="#5E616B" posicion={[0, 0.215, 0]} />
        {[-1, 1].map((l) => (
          <Pieza key={l} forma="cilindro" medidas={[0.016, 0.016, 0.04]} color="#5E616B" posicion={[0.05 * l, 0.11, 0]} rotacion={[0, 0, Math.PI / 2]} />
        ))}
        <Pieza forma="cilindro" medidas={[0.02, 0.02, 0.03]} color="#5E616B" posicion={[0, 0.1, 0.045]} rotacion={[Math.PI / 2, 0, 0]} />
      </group>

      {/* Hoja de periódico que el viento empuja por la acera */}
      <group position={[papelX, papelY, 0.66]} rotation={[-1.2 + Math.sin(frame / 9) * 0.3, frame * 0.04, Math.sin(frame / 5) * 0.4]}>
        <Pieza forma="caja" medidas={[0.12, 0.004, 0.09]} color="#CFC6B2" />
        <Pieza forma="caja" medidas={[0.08, 0.002, 0.012]} color="#5A5448" posicion={[0, 0.003, -0.025]} contorno={false} />
      </group>

      {/* Capa del fondo: farolillo del callejón y unas cajas apiladas */}
      <group position={[0.92, S, -0.42]}>
        <Sombra posicion={[0, 0.002, 0]} radio={0.1} />
        <Pieza forma="caja" medidas={[0.12, 0.09, 0.1]} color="#6A4E34" posicion={[0, 0.045, 0]} />
        <Pieza forma="caja" medidas={[0.1, 0.07, 0.09]} color="#7A5A3A" posicion={[0.01, 0.125, 0]} rotacion={[0, 0.4, 0]} />
      </group>
      <group position={[0.96, S + 0.8, 0.12]}>
        <Pieza forma="caja" medidas={[0.1, 0.012, 0.012]} color="#24262C" posicion={[-0.05, 0, 0]} />
        <Pieza forma="cono" medidas={[0.04, 0.04]} color="#2B2D33" posicion={[-0.1, -0.03, 0]} />
        <Pieza forma="esfera" medidas={[0.018]} color={paleta.acentos[3]} brillo={paleta.acentos[3]} intensidadBrillo={0.8} posicion={[-0.1, -0.05, 0]} contorno={false} />
      </group>
    </group>
  );
};

escenas.Escena5:
// Escena 6 (PASO 5): «Arriba, una ventana se abre. Un niño, David Thomas, de dos años.»
// La flecha sube por la fachada, la ventana del 4.º piso se resalta y se abre con un destello,
// y aparece asomado el niño amarillo (resaltado), con su nombre y su edad.
// Termina igual que <Mundo paso={6} />: ventana abierta, niño en la ventana y Figlock abajo con luz fría.
import React from 'react';
import {spring} from 'remotion';
import {EscenaProps, Pieza, Flecha, Etiqueta, Cartel, Linea, aparecer, momento, mover, flotar} from '../lib3d';
import {Efecto, Sombra} from '../lib25d';
import {Mundo, Ventana, Bebe, VENTANA, POS_FIGLOCK_1938} from './Mundo';

const PASO = 5;
const S = 0.08;

export const Escena5: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [rojo, gris, resalte, mostaza] = paleta.acentos;

  // ---------- Golpes sincronizados con la voz ----------
  const tArriba = momento(palabras, fps, 'Arriba', 1);
  const tVentana = momento(palabras, fps, 'ventana', 28);
  const tAbre = momento(palabras, fps, 'abre', 46);
  const tNino = momento(palabras, fps, 'niño', 83);
  const tDavid = momento(palabras, fps, 'David', 101);
  const tDos = momento(palabras, fps, 'dos', 134);

  // 1) «Arriba»: una flecha sube por la fachada desde la acera hasta la ventana.
  const subeFlecha = aparecer(frame, tArriba, 18);
  const quitaFlecha = aparecer(frame, tAbre + 6, 12);
  const flechaArriba = subeFlecha * (1 - quitaFlecha);

  // 2) «ventana»: el marco se pinta de resalte durante unos 1,2 s.
  const ventanaResaltada = frame >= tVentana && frame < tVentana + 36;

  // 3) «abre»: las hojas se abren hacia fuera con un pequeño rebote y un destello.
  const abre = spring({frame: frame - tAbre, fps, config: {damping: 11, stiffness: 120, mass: 0.7}});
  const apertura = frame < tAbre ? 0 : Math.min(1.06, abre);
  const destello = frame >= tAbre && frame < tAbre + 20 ? Math.sin(((frame - tAbre) / 20) * Math.PI) : 0;

  // 4) «niño»: el niño se asoma por el borde (sube y crece) y brilla 1,2 s.
  const asoma = spring({frame: frame - tNino, fps, config: {damping: 10, stiffness: 140, mass: 0.6}});
  const escNino = frame < tNino ? 0 : Math.min(1.08, asoma);
  const subeNino = (1 - Math.min(1, asoma)) * -0.06;
  const ninoResaltado = frame >= tNino && frame < tNino + 36;
  const pNino: [number, number, number] = [VENTANA[0], VENTANA[1] - 0.14, VENTANA[2] + 0.025];
  const flechaNino = aparecer(frame, tNino, 10) * (1 - aparecer(frame, tDavid, 8));

  // 5) «David»: etiqueta con su nombre. 6) «dos»: su edad.
  const nombre = aparecer(frame, tDavid, 10);
  const edad = aparecer(frame, tDos, 9);

  // Movimiento constante suave: el polvo de luz fría que baja y la ropa tendida que se mece.
  const viento = flotar(frame, 0.04, 70);
  const fin = Math.max(1, duracion);
  const deriva = mover(frame, [0, fin], [0, 0.05]);

  return (
    <group>
      <Mundo paso={PASO} frame={frame} fps={fps} paleta={paleta} ocultar={['ventana', 'bebe']} />

      {/* ---------- Medio: la ventana que se abre y el niño ---------- */}
      <Ventana paleta={paleta} resaltado={ventanaResaltada} abierta={apertura} frame={frame} />
      {destello > 0.01 ? (
        <Efecto tipo="destello" posicion={[VENTANA[0], VENTANA[1], VENTANA[2] + 0.1]} tam={0.5 * destello} color={mostaza} frame={frame} fps={fps} />
      ) : null}
      {escNino > 0.001 ? (
        <group position={[pNino[0], pNino[1] + subeNino, pNino[2]]} scale={escNino}>
          <group position={[-pNino[0], -pNino[1], -pNino[2]]}>
            <Bebe paleta={paleta} resaltado={ninoResaltado} donde="ventana" frame={frame} fps={fps} />
          </group>
        </group>
      ) : null}

      {/* ---------- Señales encima del mundo ---------- */}
      <Flecha desde={[0.52, 0.62, 0.5]} hasta={[0.24, 1.36, 0.34]} color={resalte} grosor={0.022} progreso={flechaArriba} />
      <Flecha desde={[0.5, 1.2, 0.42]} hasta={[0.2, 1.4, 0.3]} color={resalte} grosor={0.018} progreso={flechaNino} />
      <Etiqueta texto="david thomas" punto={[pNino[0] + 0.04, pNino[1] + 0.08, pNino[2] + 0.03]} desplazamiento={[0.55, 0.2, 0.25]} escala={nombre} color={resalte} alto={0.12} />
      <Cartel texto="2 años" posicion={[0.68, 1.34, 0.48]} alto={0.11} fondo="#1C1D25" colorTexto="#F2EFE9" escala={edad} />

      {/* ---------- Delante: boca de incendios y periódicos en la acera ---------- */}
      <group position={[-0.62, S, 0.7]}>
        <Sombra posicion={[0, 0.002, 0]} radio={0.09} />
        <Pieza forma="cilindro" medidas={[0.045, 0.05, 0.14]} color={rojo} posicion={[0, 0.07, 0]} />
        <Pieza forma="media_esfera" medidas={[0.048]} color={rojo} posicion={[0, 0.14, 0]} />
        <Pieza forma="cilindro" medidas={[0.012, 0.012, 0.13]} color="#9E3426" posicion={[0, 0.09, 0]} rotacion={[0, 0, Math.PI / 2]} />
        <Pieza forma="cilindro" medidas={[0.02, 0.02, 0.012]} color={gris} posicion={[0, 0.2, 0]} metal={0.3} />
      </group>
      <group position={[-0.08, S, 0.7]} rotation={[0, 0.35, 0]}>
        <Sombra posicion={[0, 0.002, 0]} radio={0.1} />
        <Pieza forma="caja" medidas={[0.16, 0.05, 0.11]} color="#D9D2C0" posicion={[0, 0.025, 0]} />
        <Pieza forma="caja" medidas={[0.165, 0.008, 0.02]} color="#6B5A4A" posicion={[0, 0.052, 0]} />
        <Pieza forma="caja" medidas={[0.1, 0.004, 0.06]} color="#3A3226" posicion={[-0.02, 0.054, 0.02]} contorno={false} />
      </group>

      {/* ---------- Fondo: edificios vecinos y ropa tendida sobre el callejón ---------- */}
      {[
        [-0.55, 1.35, 0.55],
        [0.2, 1.6, 0.45],
        [0.85, 1.15, 0.4],
      ].map(([x, h, w], i) => (
        <group key={i} position={[x, 0, -1.05]}>
          <Pieza forma="caja" medidas={[w, h, 0.3]} color={i % 2 ? '#2A2430' : '#241F28'} posicion={[0, h / 2, 0]} />
          <Pieza forma="caja" medidas={[w + 0.04, 0.04, 0.34]} color="#3A3340" posicion={[0, h + 0.02, 0]} />
          {[0.35, 0.75].map((y) => (
            <Pieza key={y} forma="caja" medidas={[0.08, 0.1, 0.01]} color="#3A2C1A" brillo={(i + y * 4) % 2 > 1 ? '#5E4219' : undefined} posicion={[-w * 0.2, y * h, 0.16]} contorno={false} />
          ))}
        </group>
      ))}
      <Linea desde={[0.42, S + 0.98, -0.42]} hasta={[0.95, S + 0.92, -0.42]} grosor={0.004} color="#6E7078" />
      {[0.55, 0.7, 0.84].map((x, i) => (
        <Pieza
          key={x}
          forma="caja"
          medidas={[0.07, 0.09, 0.006]}
          color={i === 1 ? '#C9C2B2' : gris}
          posicion={[x, S + 0.91 - (x - 0.42) * 0.11, -0.42]}
          rotacion={[viento * (i % 2 ? 1 : -1), 0, viento * 0.5]}
        />
      ))}

      {/* Motas de luz fría que bajan despacio sobre Figlock */}
      {[0, 1, 2, 3].map((i) => (
        <Pieza
          key={i}
          forma="esfera"
          medidas={[0.008]}
          color={mostaza}
          brillo={mostaza}
          contorno={false}
          posicion={[
            POS_FIGLOCK_1938[0] + Math.sin(i * 2.1) * 0.18,
            S + 1.2 - (((frame + i * 37) % 150) / 150) * 1.0,
            POS_FIGLOCK_1938[2] + Math.cos(i * 1.7) * 0.12 + deriva,
          ]}
        />
      ))}
    </group>
  );
};

escenas.Escena6:
// Escena 7 (PASO 6): «Se cae, y abajo, otra vez, está Figlock.»
// El niño amarillo sale de la ventana y cae despacio. La luz fría se apaga y, en «otra», el foco
// cálido cae de golpe sobre Figlock, que levanta la cabeza. Termina igual que <Mundo paso={7} />.
import React from 'react';
import {interpolate, Easing} from 'remotion';
import {EscenaProps, Pieza, Linea, Etiqueta, Aro, aparecer, momento} from '../lib3d';
import {Efecto, Sombra} from '../lib25d';
import {Mundo, Bebe, Figlock, Foco, POS_FIGLOCK_1938, VENTANA} from './Mundo';

const S = 0.08;

export const Escena6: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [, gris, calido, frio] = paleta.acentos;
  const tSe = momento(palabras, fps, 'se', 1);
  const tCae = momento(palabras, fps, 'cae', 8);
  const tAbajo = momento(palabras, fps, 'abajo', 28);
  const tOtra = momento(palabras, fps, 'otra', 48);
  const tEsta = momento(palabras, fps, 'está', 70);
  const tFig = momento(palabras, fps, 'figlock', 79);
  const fin = Math.max(tFig + 12, duracion - 1);

  const encendido = frame >= tOtra;

  // --- El niño: se asoma, se desliza fuera y cae hasta quedar suspendido (pose «aire») ---
  const asoma = aparecer(frame, tSe, Math.max(4, tCae - tSe));
  const p = interpolate(frame, [tCae, tOtra], [0, 1], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
    easing: Easing.inOut(Easing.cubic),
  });
  const aire: [number, number, number] = [VENTANA[0] + 0.05, 0.95, 0.34];
  const desdeVentana: [number, number, number] = [VENTANA[0], VENTANA[1] - 0.14, VENTANA[2] + 0.025 + 0.04];
  const off: [number, number, number] = [
    (desdeVentana[0] - aire[0]) * (1 - p),
    (desdeVentana[1] - aire[1]) * (1 - p),
    (desdeVentana[2] - aire[2]) * (1 - p),
  ];
  const bebeResaltado = frame >= tCae && frame < tCae + 38;

  // --- El foco: luz fría, apagón breve y golpe de luz cálida ---
  const apagon = frame >= tOtra - 5 && frame < tOtra;
  const golpe = encendido ? Math.exp(-(frame - tOtra) / 6) : 0;
  const fuerzaCalida = 1 + 1.4 * golpe;
  const radioCalido = 0.38 + 0.22 * golpe;

  // --- Trayectoria punteada de la caída (en «abajo») ---
  const trazo = aparecer(frame, tAbajo, 14);
  const grosorTrazo = 0.012 * interpolate(frame, [fin - 14, fin - 3], [1, 0], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});

  // --- Etiqueta «otra vez» y aro en «Figlock» (se van antes del corte) ---
  const salida = interpolate(frame, [fin - 10, fin - 2], [1, 0], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
  const etiqueta = aparecer(frame, tOtra, 8) * salida;
  const aro = aparecer(frame, tFig, 9);
  const figlockResaltado = frame >= tAbajo && frame < tAbajo + 34;
  const cabeza: [number, number, number] = [POS_FIGLOCK_1938[0], S + 0.4, POS_FIGLOCK_1938[2]];

  // Figlock tensa el cuerpo en «está»
  const tension = frame >= tEsta ? 1 + 0.04 * Math.exp(-(frame - tEsta) / 5) * Math.sin((frame - tEsta) / 1.5) : 1;

  return (
    <group>
      {/* Mundo base: el edificio pasa a la luz cálida del paso 7 en el golpe de «otra» */}
      <Mundo paso={encendido ? 7 : 6} frame={frame} fps={fps} paleta={paleta} ocultar={['bebe', 'figlock', 'foco']} />

      {/* Foco: frío hasta el apagón, cálido de golpe en «otra» */}
      {!encendido && !apagon ? (
        <Foco paleta={paleta} color={frio} fuerza={0.55} posicion={POS_FIGLOCK_1938} radio={0.42} />
      ) : null}
      {encendido ? <Foco paleta={paleta} color={calido} fuerza={fuerzaCalida} posicion={POS_FIGLOCK_1938} radio={radioCalido} /> : null}
      {encendido && frame < tOtra + 14 ? (
        <Efecto tipo="destello" posicion={[POS_FIGLOCK_1938[0], S + 0.55, POS_FIGLOCK_1938[2] + 0.05]} tam={0.5} color={calido} frame={frame - tOtra} fps={fps} />
      ) : null}

      {/* Figlock: quieto con la escoba, levanta la cabeza cuando se enciende el foco */}
      <group position={[0, 0, 0]} scale={[1, 1, 1]}>
        <group position={POS_FIGLOCK_1938} scale={[1, tension, 1]}>
          <group position={[-POS_FIGLOCK_1938[0], -POS_FIGLOCK_1938[1], -POS_FIGLOCK_1938[2]]}>
            <Figlock
              paleta={paleta}
              estado={encendido ? 'mira' : 'parado'}
              posicion={POS_FIGLOCK_1938}
              resaltado={figlockResaltado}
              frame={frame}
              fps={fps}
            />
          </group>
        </group>
      </group>

      {/* El niño */}
      {frame < tCae ? (
        <group position={[0, 0, 0.04 * asoma]}>
          <Bebe paleta={paleta} donde="ventana" frame={frame} fps={fps} />
        </group>
      ) : (
        <group position={off}>
          <Bebe paleta={paleta} donde="aire" resaltado={bebeResaltado} frame={frame} fps={fps} />
        </group>
      )}
      {frame >= tCae && frame < tCae + 10 ? (
        <Efecto tipo="ondas" posicion={[VENTANA[0], VENTANA[1] - 0.12, VENTANA[2] + 0.08]} tam={0.22} color={calido} frame={frame - tCae} fps={fps} />
      ) : null}

      {/* Camino de la caída: de la ventana al mismo punto de la acera */}
      {trazo > 0 && grosorTrazo > 0.001 ? (
        <Linea
          desde={[VENTANA[0] + 0.05, VENTANA[1] - 0.2, 0.36]}
          hasta={[POS_FIGLOCK_1938[0], S + 0.5, POS_FIGLOCK_1938[2] + 0.02]}
          color={calido}
          grosor={grosorTrazo}
          progreso={trazo}
          discontinua
          brillo
        />
      ) : null}

      {/* «otra vez», al lado del callejón, señalando a Figlock */}
      <Etiqueta texto="otra vez" punto={cabeza} desplazamiento={[0.5, 0.42, 0.12]} escala={etiqueta} color={calido} />
      {aro > 0 && frame < fin - 1 ? (
        <Aro posicion={[POS_FIGLOCK_1938[0], S, POS_FIGLOCK_1938[2]]} radio={0.18 + 0.12 * aro} color={calido} progreso={aro} />
      ) : null}

      {/* Delante: boca de incendios en el bordillo y papeles sueltos en la acera */}
      <group position={[-0.62, S, 0.7]}>
        <Sombra posicion={[0, 0.002, 0]} radio={0.09} />
        <Pieza forma="cilindro" medidas={[0.05, 0.055, 0.03]} color="#3A3D46" posicion={[0, 0.015, 0]} />
        <Pieza forma="cilindro" medidas={[0.038, 0.042, 0.16]} color={paleta.acentos[0]} posicion={[0, 0.11, 0]} />
        <Pieza forma="media_esfera" medidas={[0.04]} color={paleta.acentos[0]} posicion={[0, 0.19, 0]} />
        <Pieza forma="cilindro" medidas={[0.012, 0.012, 0.03]} color={gris} posicion={[0, 0.235, 0]} metal={0.4} />
        {[-1, 1].map((l) => (
          <Pieza key={l} forma="cilindro" medidas={[0.016, 0.016, 0.04]} color={gris} posicion={[0.05 * l, 0.13, 0]} rotacion={[0, 0, Math.PI / 2]} metal={0.4} />
        ))}
        <Pieza forma="cilindro" medidas={[0.02, 0.02, 0.03]} color={gris} posicion={[0, 0.12, 0.045]} rotacion={[Math.PI / 2, 0, 0]} metal={0.4} />
      </group>
      {[
        [-0.25, 0.68, 0.4],
        [0.05, 0.62, -0.6],
        [0.62, 0.7, 1.1],
      ].map(([x, z, r], i) => (
        <Pieza key={i} forma="caja" medidas={[0.07, 0.003, 0.05]} color={i === 1 ? '#CDB77E' : '#D9C48E'} posicion={[x, S + 0.003, z]} rotacion={[0, r, 0]} contorno={false} />
      ))}
    </group>
  );
};

escenas.Escena8:
// Escena 9 · PASO 8 → 9: «Esto lo contó la revista Time, en octubre de mil novecientos treinta y ocho.»
// El foco cálido deja a Figlock y al niño y sube hasta el recorte gigante de la revista Time,
// que gira y se asienta flotando sobre el callejón. El barrio se queda en penumbra.
import React from 'react';
import {EscenaProps, Pieza, Brillo, Etiqueta, Flecha, aparecer, momento, mover, rebote, flotar} from '../lib3d';
import type {V3} from '../lib3d';
import {Efecto, Sombra} from '../lib25d';
import {Mundo, Revista, Escoba, Foco, POS_REVISTA, POS_FIGLOCK_1938} from './Mundo';

const S = 0.08;
const PAPEL = '#D9C48E';
const PAPEL_OSC = '#CDB77E';

export const Escena8: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const resalte = paleta.acentos[2];

  // Golpes sincronizados con la voz
  const tEsto = momento(palabras, fps, 'esto', 1);
  const tRevista = momento(palabras, fps, 'revista', 26);
  const tTime = momento(palabras, fps, 'time', 39);
  const tOctubre = momento(palabras, fps, 'octubre', 60);
  const tTreinta = momento(palabras, fps, 'treinta', 100);

  // El mundo pasa a penumbra justo cuando la voz dice «Time»
  const paso = frame < tTime ? 8 : 9;

  // 1) El foco se despega de Figlock y viaja hasta el sitio del recorte
  const viaje = aparecer(frame, tEsto, Math.max(12, tTime - tEsto));
  const focoIni: V3 = [POS_FIGLOCK_1938[0], S, POS_FIGLOCK_1938[2]];
  const focoFin: V3 = [POS_REVISTA[0], S, POS_REVISTA[2]];
  const focoPos: V3 = [
    focoIni[0] + (focoFin[0] - focoIni[0]) * viaje,
    S,
    focoIni[2] + (focoFin[2] - focoIni[2]) * viaje,
  ];
  const focoRadio = 0.38 + (0.55 - 0.38) * viaje;
  const golpeLuz = Math.exp(-Math.max(0, frame - tTime) / 6) * (frame >= tTime ? 0.5 : 0);
  const focoFuerza = 1.15 - 0.15 * viaje + golpeLuz;

  // 2) La escoba tirada se retira hacia la sombra (en el paso 9 ya no está)
  const escobaFuera = aparecer(frame, tRevista - 4, 14);
  const escobaEsc = 1 - escobaFuera;

  // 3) El recorte entra girando desde arriba y se asienta
  const entra = rebote(frame, fps, tRevista - 4);
  const asienta = aparecer(frame, tRevista - 4, Math.max(10, tTime - tRevista + 4));
  const revY = (1 - asienta) * 0.55;
  const revGiro = (1 - asienta) * 1.7;
  const revEsc = Math.max(0, entra);
  const revResaltada = frame >= tTime && frame < tTime + 32;

  // 4) La fecha: subrayado al decir «octubre», etiqueta con el año al decir «treinta»
  const subraya = aparecer(frame, tOctubre, 10);
  const etqTime = aparecer(frame, tTime + 2, 8) * (1 - aparecer(frame, tTreinta - 4, 6));
  const etqFecha = aparecer(frame, tTreinta, 8);
  const flechaFecha = aparecer(frame, tOctubre, 12) * (1 - aparecer(frame, duracion - 8, 8));

  const fl = flotar(frame, 0.012, 100);
  const revCentro: V3 = [POS_REVISTA[0], POS_REVISTA[1] + fl, POS_REVISTA[2]];

  // Polvo flotando dentro del haz de luz (movimiento constante)
  const polvo = Array.from({length: 9}, (_, i) => {
    const t = frame / fps;
    const x = focoPos[0] + Math.sin(i * 2.1 + t * 0.7) * focoRadio * 0.6;
    const z = focoPos[2] + Math.cos(i * 1.7 + t * 0.5) * 0.18;
    const y = 0.2 + ((i * 0.19 + t * 0.06) % 1.4);
    return <Brillo key={i} posicion={[x, y, z]} color="#F7DFA8" radio={0.008 + (i % 3) * 0.003} />;
  });

  // Hojitas sueltas en la acera (primer plano) que se agitan con el aire
  const hoja = (x: number, z: number, g: number, k: number) => (
    <group key={k} position={[x, S + 0.006 + Math.max(0, Math.sin(frame / 9 + k)) * 0.01, z]} rotation={[0, g + Math.sin(frame / 14 + k) * 0.08, 0]}>
      <Pieza forma="caja" medidas={[0.16, 0.006, 0.2]} color={k % 2 ? PAPEL_OSC : PAPEL} />
      <Pieza forma="caja" medidas={[0.1, 0.004, 0.012]} color="#3A3226" posicion={[0, 0.005, 0.05]} contorno={false} />
      <Pieza forma="caja" medidas={[0.12, 0.004, 0.012]} color="#3A3226" posicion={[0, 0.005, 0]} contorno={false} />
      <Sombra posicion={[0, -0.004, 0]} radio={0.12} />
    </group>
  );
  // Una hoja que cae delante, cerca de la cámara
  const caidaY = mover(frame, [0, duracion], [1.5, 0.35]);
  const caidaX = 0.95 + Math.sin(frame / 12) * 0.08;

  return (
    <group>
      <Mundo paso={paso} frame={frame} fps={fps} paleta={paleta} ocultar={['foco', 'revista', 'escoba']} />

      {/* Foco que viaja de Figlock al recorte */}
      <Foco paleta={paleta} color={resalte} fuerza={focoFuerza} posicion={focoPos} radio={focoRadio} />
      {polvo}

      {/* Escoba tirada que se encoge hacia la sombra */}
      {escobaEsc > 0.001 ? (
        <group position={[0.55, S + 0.02, 0.62]} scale={escobaEsc}>
          <group position={[-0.55, -(S + 0.02), -0.62]}>
            <Escoba paleta={paleta} estado="tirada" />
          </group>
        </group>
      ) : null}

      {/* El recorte de la revista Time entra girando y se asienta */}
      {revEsc > 0.001 ? (
        <group position={[POS_REVISTA[0], POS_REVISTA[1] + revY, POS_REVISTA[2]]} rotation={[0, revGiro, 0]} scale={revEsc}>
          <group position={[-POS_REVISTA[0], -POS_REVISTA[1], -POS_REVISTA[2]]}>
            <Revista paleta={paleta} resaltado={revResaltada} frame={frame} />
          </group>
        </group>
      ) : null}

      {/* Destello al decir «Time» */}
      {frame >= tTime && frame < tTime + 20 ? (
        <Efecto tipo="destello" posicion={[revCentro[0], revCentro[1] + 0.2, revCentro[2] + 0.05]} tam={0.9} frame={frame - tTime} fps={fps} />
      ) : null}

      {/* Subrayado de la fecha impresa en el recorte */}
      <group position={revCentro} rotation={[0, -0.12, 0.05]}>
        <Pieza
          forma="caja"
          medidas={[0.5, 0.014, 0.01]}
          color={resalte}
          brillo={resalte}
          intensidadBrillo={0.6}
          posicion={[0, -0.485, 0.02]}
          escala={[Math.max(0.002, subraya), 1, 1]}
        />
      </group>
      <Flecha desde={[1.0, 0.62, 0.95]} hasta={[0.72, 0.6, 0.8]} color={resalte} grosor={0.018} progreso={flechaFecha} />

      {/* Rótulos: solo cuando la voz los nombra, a un lado del recorte */}
      <Etiqueta texto="revista time" punto={[revCentro[0] - 0.3, revCentro[1] + 0.44, revCentro[2] + 0.03]} desplazamiento={[-0.55, 0.3, 0.05]} escala={etqTime} />
      <Etiqueta texto="time, 1938" punto={[revCentro[0] - 0.22, revCentro[1] - 0.45, revCentro[2] + 0.03]} desplazamiento={[-0.6, -0.12, 0.1]} escala={etqFecha} color={resalte} />

      {/* Primer plano: hojas sueltas en la acera y una que cae delante */}
      {hoja(-0.72, 0.68, 0.4, 0)}
      {hoja(-0.48, 0.74, -0.5, 1)}
      <group position={[caidaX, caidaY, 1.0]} rotation={[0.6 + Math.sin(frame / 10) * 0.4, frame / 20, Math.sin(frame / 8) * 0.3]}>
        <Pieza forma="caja" medidas={[0.12, 0.005, 0.15]} color={PAPEL} />
      </group>
    </group>
  );
};

escenas.Escena7:
// Escena 8 · «Cae sobre él, de nuevo. Y de nuevo, los dos sobreviven.»
// El niño amarillo cae y aterriza sobre Figlock: Figlock se aplasta como en los dibujos animados y la escoba sale volando.
// Los dos quedan sentados en el callejón mientras el foco cálido crece y forma un halo.
// Al terminar, todo queda igual que <Mundo paso={8} />.
import React from 'react';
import {EscenaProps, Pieza, Linea, Aro, Etiqueta, aparecer, momento, mover, flotar} from '../lib3d';
import type {V3} from '../lib3d';
import {Efecto, Sombra} from '../lib25d';
import {Mundo, Bebe, Figlock, Escoba, Foco, VENTANA, POS_FIGLOCK_1938, focoDe} from './Mundo';

const PASO = 7;
const S = 0.08;

const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
const lerp3 = (a: V3, b: V3, t: number): V3 => [lerp(a[0], b[0], t), lerp(a[1], b[1], t), lerp(a[2], b[2], t)];
const clamp = (v: number) => Math.max(0, Math.min(1, v));

export const Escena7: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [, , resalte, extra] = paleta.acentos;
  const fin = Math.max(60, duracion);

  // ---------- Golpes sincronizados con la voz ----------
  const tCae = momento(palabras, fps, 'Cae', 1);
  const tEl = Math.max(tCae + 10, momento(palabras, fps, 'él', 20));
  const tNuevo = Math.max(tEl + 6, momento(palabras, fps, 'nuevo', 35));
  const tY = momento(palabras, fps, 'Y', 70);
  const tNuevo2 = Math.max(tNuevo + 20, tY + 7);
  const tDos = Math.max(tNuevo2 + 10, momento(palabras, fps, 'dos', 100));
  const tSob = Math.max(tDos + 3, momento(palabras, fps, 'sobreviven', 105));
  const tLimpia = fin - 8; // los textos se retiran para cerrar igual que el paso 8

  const pos = POS_FIGLOCK_1938;

  // ---------- El niño: cae, rebota y se sienta ----------
  const airePos: V3 = [VENTANA[0] + 0.05, 0.95 + flotar(frame, 0.01, 50), 0.34];
  const sentadoPos: V3 = [pos[0] + 0.14, S, pos[2] + 0.05];
  const impacto: V3 = [pos[0], S + 0.4, pos[2] + 0.02];
  const caida = clamp((frame - tCae) / Math.max(1, tEl - tCae));
  const enAire = frame < tEl;
  let ninoPos: V3;
  if (enAire) {
    const g = caida * caida; // acelera como con gravedad
    ninoPos = lerp3(airePos, impacto, g);
  } else {
    const salto = clamp((frame - tEl) / 12);
    const base = lerp3(impacto, sentadoPos, salto);
    const arco = Math.sin(salto * Math.PI) * 0.16;
    const asienta = frame > tEl + 12 ? Math.abs(Math.sin((frame - tEl - 12) / 2.2)) * Math.exp(-(frame - tEl - 12) / 5) * 0.03 : 0;
    ninoPos = [base[0], base[1] + arco + asienta, base[2]];
  }
  const ninoRef = enAire ? airePos : sentadoPos;
  const ninoOff: V3 = [ninoPos[0] - ninoRef[0], ninoPos[1] - ninoRef[1], ninoPos[2] - ninoRef[2]];

  // ---------- Figlock: mira, se aplasta, queda sentado ----------
  const cambio = tEl + 4;
  const estadoF = frame < cambio ? 'mira' : 'sentado';
  let sy = 1;
  let sx = 1;
  if (frame >= tEl && frame < cambio) {
    const k = (frame - tEl) / 4;
    sy = lerp(1, 0.72, k);
    sx = lerp(1, 1.2, k);
  } else if (frame >= cambio) {
    const f = frame - cambio;
    const w = Math.exp(-f / 6) * Math.sin(f / 1.7);
    sy = 1 - 0.18 * Math.exp(-f / 4) + 0.08 * w;
    sx = 1 + 0.12 * Math.exp(-f / 4) - 0.05 * w;
  }

  // ---------- La escoba sale volando y cae tirada ----------
  const manoPos: V3 = [pos[0] + 0.12, S, pos[2] + 0.04];
  const tiradaPos: V3 = [0.55, S + 0.02, 0.62];
  const vuelo = clamp((frame - tEl) / 16);
  const escobaPos = lerp3(manoPos, tiradaPos, vuelo);
  escobaPos[1] += Math.sin(vuelo * Math.PI) * 0.38;
  const escobaRot: V3 = [0, lerp(0, 0.45, vuelo), lerp(0.28, Math.PI / 2 + Math.PI * 2, vuelo)];
  const escobaRebote = vuelo >= 1 ? Math.abs(Math.sin((frame - tEl - 16) / 1.8)) * Math.exp(-(frame - tEl - 16) / 4) * 0.025 : 0;

  // ---------- El foco cálido se convierte en halo ----------
  const foco7 = focoDe(PASO, paleta);
  const foco8 = focoDe(PASO + 1, paleta);
  const destelloFoco = frame >= tEl ? Math.exp(-(frame - tEl) / 6) * 0.6 : 0;
  const pulso = mover(frame, [tNuevo2 - 2, tNuevo2 + 6, tNuevo2 + 22], [foco7.fuerza, 1.35, foco8.fuerza]);
  const fuerzaFoco = frame < tNuevo2 - 2 ? lerp(foco7.fuerza, foco8.fuerza, aparecer(frame, tNuevo, 20)) + destelloFoco : pulso;

  // Anillo de luz que se expande al decir «sobreviven» y se apaga antes del final
  const anillo = clamp((frame - tSob) / 14);
  const verAnillo = frame >= tSob && anillo < 1;

  // Trayectoria discontinua de la caída: de la ventana al hombro de Figlock
  const tray = aparecer(frame, tNuevo, 12);
  const recoge = aparecer(frame, tDos - 8, 10);
  const trayDesde = lerp3([VENTANA[0] + 0.05, VENTANA[1] - 0.18, 0.34], [pos[0], S + 0.42, pos[2] + 0.02], recoge);

  // ---------- Resaltes ----------
  const resaltaFig = (frame >= tEl && frame < tEl + 36) || (frame >= tDos && frame < tLimpia);
  const resaltaNino = frame >= tDos && frame < tLimpia;

  // ---------- Textos ----------
  const txtNuevo = aparecer(frame, tNuevo2, 8) * (1 - aparecer(frame, tDos - 2, 6));
  const txtSob = aparecer(frame, tSob, 8) * (1 - aparecer(frame, tLimpia, 6));

  return (
    <group>
      <Mundo paso={PASO} frame={frame} fps={fps} paleta={paleta} ocultar={['bebe', 'figlock', 'escoba', 'foco']} />

      {/* foco cálido que crece hasta ser el halo del paso 8 */}
      <Foco paleta={paleta} color={foco8.color} fuerza={fuerzaFoco} posicion={foco8.pos} radio={foco8.radio} />

      {/* Figlock (aplastamiento de dibujo animado y luego sentado) */}
      <group position={pos} scale={[sx, sy, 1]}>
        <Figlock paleta={paleta} estado={estadoF} posicion={[0, 0, 0]} resaltado={resaltaFig} frame={frame} fps={fps} />
      </group>

      {/* el niño */}
      <group position={ninoOff}>
        <Bebe paleta={paleta} donde={enAire ? 'aire' : 'sentado'} resaltado={resaltaNino} frame={frame} fps={fps} />
      </group>
      {enAire ? <Sombra posicion={[ninoPos[0], S + 0.003, ninoPos[2]]} radio={0.04 + 0.05 * caida} /> : null}

      {/* la escoba: vuela y queda tirada exactamente como en el paso 8 */}
      {vuelo < 1 ? (
        <group position={escobaPos} rotation={escobaRot}>
          <Pieza forma="caja" medidas={[0.14, 0.04, 0.035]} color="#C9A35A" posicion={[0, 0.02, 0]} />
          <Pieza forma="caja" medidas={[0.13, 0.03, 0.045]} color="#4A3326" posicion={[0, 0.055, 0]} />
          <Pieza forma="cilindro" medidas={[0.008, 0.009, 0.4]} color="#8A5A34" posicion={[0, 0.27, 0]} />
        </group>
      ) : (
        <group position={[0, escobaRebote, 0]}>
          <Escoba paleta={paleta} estado="tirada" posicion={pos} />
        </group>
      )}
      {vuelo > 0 && vuelo < 1 ? <Sombra posicion={[escobaPos[0], S + 0.003, escobaPos[2]]} radio={0.08} /> : null}

      {/* golpe del aterrizaje: destello y polvo a ras de suelo (delante) */}
      {frame >= tEl && frame < tEl + 12 ? (
        <Efecto tipo="destello" posicion={[pos[0], S + 0.42, pos[2] + 0.1]} tam={0.38} color={resalte} frame={frame - tEl} fps={fps} />
      ) : null}
      {frame >= tEl + 3 && frame < tEl + 26 ? (
        <Efecto tipo="vapor" posicion={[pos[0] + 0.05, S + 0.03, pos[2] + 0.16]} tam={0.32} color="#8C8F99" frame={frame - tEl} fps={fps} />
      ) : null}

      {/* trayectoria de la caída */}
      {tray > 0 && recoge < 1 ? (
        <Linea desde={trayDesde} hasta={lerp3(trayDesde, [pos[0], S + 0.42, pos[2] + 0.02], tray > 0 ? 1 : 0)} grosor={0.007} color={extra} discontinua progreso={tray} brillo />
      ) : null}

      {/* anillo de luz al «sobreviven» */}
      {verAnillo ? (
        <Aro posicion={[pos[0] + 0.06, S, pos[2] + 0.02]} radio={0.3 + anillo * 0.45} grosor={0.022 * (1 - anillo) + 0.003} color={resalte} />
      ) : null}

      {/* textos: solo cuando la voz los dice */}
      <Etiqueta texto="de nuevo" punto={[pos[0] - 0.05, S + 0.2, pos[2] + 0.02]} desplazamiento={[-0.62, 0.5, 0.25]} escala={txtNuevo} color={resalte} />
      <Etiqueta texto="sobreviven" punto={[pos[0] + 0.1, S + 0.24, pos[2] + 0.04]} desplazamiento={[0.32, 0.72, 0.2]} escala={txtSob} color={resalte} />
    </group>
  );
};

escenas.Escena9:
// Escena 10: «Pero ojo: es una nota breve de una sola revista, y hoy casi todo son copias de ella.
// Faltan otras fuentes que la confirmen.»
// El recorte de Time se resalta y se queda solo. Después salen de él copias idénticas que se apilan
// en la acera mientras el original se pierde en la sombra. Al final, dos marcos vacíos en rojo
// muestran las fuentes que faltan.
// Termina igual que <Mundo paso={10} />: la pila bajo un solo foco, la ventana cerrada y el callejón oscuro.
import React from 'react';
import {EscenaProps, Pieza, Linea, Etiqueta, aparecer, momento, mover} from '../lib3d';
import type {V3} from '../lib3d';
import {
  Mundo,
  Revista,
  Copias,
  Foco,
  Figlock,
  Bebe,
  Ventana,
  POS_REVISTA,
  POS_COPIAS,
  POS_FIGLOCK_1938,
} from './Mundo';

const S = 0.08;
const N = 10; // copias de la pila (igual que en Mundo paso 10)
const PAPEL = '#D9C48E';
const PAPEL_OSC = '#CDB77E';

const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

/** Marco vacío con borde de trazos: la fuente que no está. */
const MarcoVacio: React.FC<{centro: V3; ancho: number; alto: number; color: string; progreso: number}> = ({centro, ancho, alto, color, progreso}) => {
  if (progreso <= 0.001) return null;
  const [x, y, z] = centro;
  const w = ancho / 2;
  const h = alto / 2;
  const esq: V3[] = [
    [x - w, y + h, z],
    [x + w, y + h, z],
    [x + w, y - h, z],
    [x - w, y - h, z],
  ];
  return (
    <group>
      {esq.map((p, i) => (
        <Linea key={i} desde={p} hasta={esq[(i + 1) % 4]} grosor={0.007} color={color} brillo discontinua progreso={Math.min(1, Math.max(0, progreso * 4 - i))} />
      ))}
    </group>
  );
};

export const Escena9: React.FC<EscenaProps> = ({frame, fps, palabras, paleta}) => {
  const [rojo, , resalte] = paleta.acentos;

  const tOjo = momento(palabras, fps, 'ojo', 8);
  const tNota = momento(palabras, fps, 'nota', 36);
  const tSola = momento(palabras, fps, 'sola', 63);
  const tHoy = momento(palabras, fps, 'hoy', 97);
  const tCopias = momento(palabras, fps, 'copias', 127);
  const tFaltan = momento(palabras, fps, 'faltan', 176);
  const tConfirmen = momento(palabras, fps, 'confirmen', 214);

  // Golpe 1 («ojo»): el recorte da un respingo y el foco se cierra un instante.
  const respingo = mover(frame, [tOjo - 2, tOjo + 4, tOjo + 14], [0, 1, 0]);
  // Golpe 2 («nota breve»): el recorte se pinta del color de resalte durante 1,2 s.
  const notaResaltada = frame >= tNota && frame < tNota + 36;
  // Golpe 3 («sola»): etiqueta «una sola fuente».
  const etiqueta = aparecer(frame, tSola, 10) * (1 - aparecer(frame, tCopias - 6, 8));
  // «hoy»: la ventana se cierra, y Figlock y el niño se van a la sombra.
  const cierra = aparecer(frame, tHoy, 12);
  const gente = 1 - aparecer(frame, tHoy + 4, 14);

  // «copias»: cada 3 fotogramas sale una copia del recorte y vuela a la pila.
  const VUELO = 10;
  const llegada = (i: number) => tCopias + i * 3;
  let apiladas = 0;
  for (let i = 0; i < N; i++) if (frame >= llegada(i)) apiladas++;
  const pilaAparece = aparecer(frame, llegada(0) - 2, 6);

  // El original retrocede hacia la oscuridad y desaparece.
  const salida = aparecer(frame, tCopias + 8, 38);
  const revEscala = (1 + 0.06 * respingo) * (1 - salida);
  const revOffset: V3 = [0.1 * salida, -0.15 * salida, -0.55 * salida];

  // El foco pasa del recorte a la pila.
  const kFoco = aparecer(frame, tCopias - 4, 26);
  const focoPos: V3 = [lerp(POS_REVISTA[0], POS_COPIAS[0], kFoco), S, lerp(POS_REVISTA[2], POS_COPIAS[2], kFoco)];
  const focoRadio = lerp(0.55, 0.45, kFoco) * (1 - 0.18 * respingo);

  // «Faltan otras fuentes»: dos marcos vacíos en rojo, con una luz roja de alarma.
  const fuentes = aparecer(frame, tFaltan, 16) * (1 - aparecer(frame, tConfirmen + 2, 12));
  const latido = 0.75 + 0.25 * Math.sin((frame - tFaltan) * 0.35);

  // Copias en vuelo: salen del recorte (de pie, mirando a la cámara) y caen planas en la pila.
  const enVuelo: React.ReactNode[] = [];
  for (let i = 0; i < N; i++) {
    const t0 = llegada(i) - VUELO;
    if (frame < t0 || frame >= llegada(i)) continue;
    const k = (frame - t0) / VUELO;
    const e = k * k * (3 - 2 * k);
    const desde: V3 = [POS_REVISTA[0] + revOffset[0], POS_REVISTA[1] + revOffset[1], POS_REVISTA[2] + revOffset[2] + 0.03];
    const hasta: V3 = [POS_COPIAS[0] + Math.sin(i * 1.3) * 0.03, S + 0.006 + i * 0.013, POS_COPIAS[2] + Math.cos(i * 1.7) * 0.02];
    const arco = Math.sin(Math.PI * e) * 0.22;
    enVuelo.push(
      <Pieza
        key={i}
        forma="caja"
        medidas={[0.5, 0.012, 0.62]}
        color={i % 2 ? PAPEL_OSC : PAPEL}
        posicion={[lerp(desde[0], hasta[0], e) + (i % 2 ? 0.12 : -0.12) * Math.sin(Math.PI * e), lerp(desde[1], hasta[1], e) + arco, lerp(desde[2], hasta[2], e)]}
        rotacion={[(Math.PI / 2) * (1 - e), Math.sin(i * 2.3) * 0.25 * e, (i % 2 ? -0.5 : 0.5) * Math.sin(Math.PI * e)]}
        escala={lerp(0.75, 1, e)}
      />,
    );
  }

  return (
    <group>
      <Mundo paso={9} frame={frame} fps={fps} paleta={paleta} ocultar={['revista', 'foco', 'figlock', 'bebe', 'ventana']} />

      {/* fondo: la ventana se cierra; Figlock y el niño se pierden en el callejón oscuro */}
      <Ventana paleta={paleta} abierta={1 - cierra} frame={frame} />
      {gente > 0.001 ? (
        <group position={POS_FIGLOCK_1938} scale={gente}>
          <group position={[-POS_FIGLOCK_1938[0], -POS_FIGLOCK_1938[1], -POS_FIGLOCK_1938[2]]}>
            <Figlock paleta={paleta} estado="sentado" posicion={POS_FIGLOCK_1938} frame={frame} fps={fps} />
            <Bebe paleta={paleta} donde="sentado" frame={frame} fps={fps} />
          </group>
        </group>
      ) : null}

      {/* el único foco: del recorte a la pila */}
      <Foco paleta={paleta} color={resalte} fuerza={1} posicion={focoPos} radio={focoRadio} />

      {/* medio: el recorte original, que se va a la sombra */}
      {revEscala > 0.001 ? (
        <group position={[POS_REVISTA[0] + revOffset[0], POS_REVISTA[1] + revOffset[1], POS_REVISTA[2] + revOffset[2]]} scale={revEscala}>
          <group position={[-POS_REVISTA[0], -POS_REVISTA[1], -POS_REVISTA[2]]}>
            <Revista paleta={paleta} resaltado={notaResaltada} frame={frame} />
          </group>
        </group>
      ) : null}
      <Etiqueta texto="una sola fuente" punto={[-0.04, 1.32, 0.72]} desplazamiento={[-0.5, 0.32, 0.1]} escala={etiqueta} color={resalte} />

      {/* las copias: vuelan y se apilan */}
      {enVuelo}
      {apiladas > 0 ? (
        <group position={POS_COPIAS} scale={0.6 + 0.4 * pilaAparece}>
          <group position={[-POS_COPIAS[0], -POS_COPIAS[1], -POS_COPIAS[2]]}>
            <Copias paleta={paleta} cantidad={apiladas} />
          </group>
        </group>
      ) : null}

      {/* delante: las fuentes que faltan, marcos vacíos con luz roja */}
      {fuentes > 0.001 ? (
        <group>
          <MarcoVacio centro={[-0.5, 0.95, 0.9]} ancho={0.36} alto={0.46} color={rojo} progreso={fuentes} />
          <MarcoVacio centro={[-0.86, 0.62, 0.8]} ancho={0.3} alto={0.38} color={rojo} progreso={aparecer(frame, tFaltan + 8, 16) * (1 - aparecer(frame, tConfirmen + 2, 12))} />
          <pointLight color={rojo} intensity={1.6 * fuentes * latido} distance={2.2} decay={2} position={[-0.6, 0.9, 1.1]} />
        </group>
      ) : null}
    </group>
  );
};
